/// Test whether a sector's world-space AABB could overlap a CSM cascade's
/// ortho frustum. Transforms the 8 AABB corners by the cascade view-proj
/// matrix and checks the projected AABB against the Vulkan clip volume.
///
/// Conservative: may return true when no overlap exists (wastes a cascade
/// re-render — benign), but never returns false when there IS overlap
/// (would leave stale shadow data — a correctness bug).
///
/// Uses the *previous frame's* cascade VP matrices (`csm_last_view_proj`)
/// because the static cache was rendered with those matrices. If the
/// camera moved enough to shift a cascade frustum onto the new sector
/// since last frame, the per-cascade matrix change detection in the CSM
/// dirty-check block (lines ~6458-6467) catches it independently.
///

/// Conservative: may return true when no overlap exists (wastes a cascade
/// re-render — benign), but never returns false when there IS overlap
/// (would leave stale shadow data — a correctness bug).
///
/// Uses the *previous frame's* cascade VP matrices (`csm_last_view_proj`)
/// because the static cache was rendered with those matrices. If the
/// camera moved enough to shift a cascade frustum onto the new sector
/// since last frame, the per-cascade matrix change detection in the CSM
/// dirty-check block (lines ~6458-6467) catches it independently.
///
/// Y range is conservative: [-5, 30] covers any geometry in the sector
/// without requiring per-sector height tracking. The main discriminating
/// axis is XZ — a 25 m sector at 100 m distance won't overlap cascade 0
/// (32 m ortho bounds) regardless of Y.
fn sector_overlaps_csm_cascade(
    coord: (i32, i32),
    sector_size: f32,
    cascade_vp: &[[f32; 4]; 4],
) -> bool {
    let sx = coord.0 as f32 * sector_size;
    let sz = coord.1 as f32 * sector_size;
    let ex = sx + sector_size;
    let ez = sz + sector_size;

    const Y_MIN: f32 = -5.0;
    const Y_MAX: f32 = 30.0;

    // 8 AABB corners.
    let corners: [[f32; 3]; 8] = [
        [sx, Y_MIN, sz], [ex, Y_MIN, sz], [sx, Y_MIN, ez], [ex, Y_MIN, ez],
        [sx, Y_MAX, sz], [ex, Y_MAX, sz], [sx, Y_MAX, ez], [ex, Y_MAX, ez],
    ];

    // Column-major mat4×vec4: result = VP × [x, y, z, 1].
    // cascade_vp[col][row] — glam's to_cols_array_2d() layout.
    let mut ndc_min = [f32::MAX; 3];
    let mut ndc_max = [f32::MIN; 3];
    let vp = cascade_vp;

    for c in &corners {
        let x = vp[0][0] * c[0] + vp[1][0] * c[1] + vp[2][0] * c[2] + vp[3][0];
        let y = vp[0][1] * c[0] + vp[1][1] * c[1] + vp[2][1] * c[2] + vp[3][1];
        let z = vp[0][2] * c[0] + vp[1][2] * c[1] + vp[2][2] * c[2] + vp[3][2];
        let w = vp[0][3] * c[0] + vp[1][3] * c[1] + vp[2][3] * c[2] + vp[3][3];

        // Ortho: w ≈ 1.0 always. Perspective divide handles any edge case.
        let inv_w = if w.abs() > 1e-6 { 1.0 / w } else { continue };
        let nx = x * inv_w;
        let ny = y * inv_w;
        let nz = z * inv_w;

        ndc_min[0] = ndc_min[0].min(nx);
        ndc_min[1] = ndc_min[1].min(ny);
        ndc_min[2] = ndc_min[2].min(nz);
        ndc_max[0] = ndc_max[0].max(nx);
        ndc_max[1] = ndc_max[1].max(ny);
        ndc_max[2] = ndc_max[2].max(nz);
    }

    // Vulkan NDC: x ∈ [-1,1], y ∈ [-1,1], z ∈ [0,1].

        ndc_min[0] = ndc_min[0].min(nx);
        ndc_min[1] = ndc_min[1].min(ny);
        ndc_min[2] = ndc_min[2].min(nz);
        ndc_max[0] = ndc_max[0].max(nx);
        ndc_max[1] = ndc_max[1].max(ny);
        ndc_max[2] = ndc_max[2].max(nz);
    }

    // Vulkan NDC: x ∈ [-1,1], y ∈ [-1,1], z ∈ [0,1].
    // AABB-vs-AABB overlap: each axis must have intersecting ranges.
    ndc_max[0] >= -1.0 && ndc_min[0] <= 1.0
        && ndc_max[1] >= -1.0 && ndc_min[1] <= 1.0
        && ndc_max[2] >= 0.0 && ndc_min[2] <= 1.0
}

/// AO buffer format (shared by GTAO and HBAO): 16-bit float for smooth
/// gradients at 4K. Eliminates visible quantization banding in dark
/// ambient-only corners. 4.1MB at 1080p half-res, 16.6MB at 4K half-res.
const AO_FORMAT: vk::Format = vk::Format::R16_SFLOAT;
/// Motion vectors: 2-channel half-float, NDC-space velocity.
/// 8.3MB at 1080p (1920×1080 × 4B). Phase 5.1.
const MOTION_VECTORS_FORMAT: vk::Format = vk::Format::R16G16_SFLOAT;

/// Scene color: HDR linear lighting output, read by composite + SSR.
/// 16.6MB at 1080p (1920×1080 × 8B). Phase 5.3-prep.
const SCENE_COLOR_FORMAT: vk::Format = vk::Format::R16G16B16A16_SFLOAT;

/// AO resolution mode. `true` = half resolution, `false` = native.
///
/// Half-res saves ~0.6–1.2ms/frame (4× fewer GTAO compute invocations)
/// with negligible quality impact: the bilateral blur preserves depth
/// edges, and the lighting shader's bilinear sampler provides smooth
/// upsampling from the smaller AO texture.
///
/// At 1080p: native = 2M pixels × 64 fetches = 128M reads.
///           half   = 0.5M pixels × 64 fetches = 32M reads.
const AO_HALF_RES: bool = true;

/// Volumetric scatter resolution mode. `true` = half-resolution VPS+VSS
/// with depth-aware bilateral upsample in lighting.frag. `false` = native.
///
/// Half-res is a ~4× reduction in both shader invocations and, for VSS,
/// CSM shadow-map samples — the dominant cost of the entire vol chain.
///
///   Native 1080p VSS: 48 CSM-PCF taps × 2.07M pixels = ~99M shadow reads.
///   Half   1080p VSS: 48 CSM-PCF taps × 0.52M pixels = ~25M shadow reads.
///
/// Quality cost is minor: both outputs are low-frequency (HG phase is
/// smooth, shaft detail comes pre-filtered through CSM-PCF). A 4-tap
/// depth-aware bilateral filter in lighting.frag reconstructs edges.
///
/// VSS's alpha channel (unshadowed luminance reference, used for the
/// shaft mask) is upsampled with the same bilateral weights so the
/// ratio `volSunScatter.rgb / unshadowedRef` stays consistent per pixel.
const VOL_SCATTER_HALF_RES: bool = true;

/// RT reflection resolution mode. `true` = half resolution with bilinear
/// upsample in lighting.frag. `false` = full (native) resolution.
///

/// depth-aware bilateral filter in lighting.frag reconstructs edges.
///
/// VSS's alpha channel (unshadowed luminance reference, used for the
/// shaft mask) is upsampled with the same bilateral weights so the
/// ratio `volSunScatter.rgb / unshadowedRef` stays consistent per pixel.
const VOL_SCATTER_HALF_RES: bool = true;

/// RT reflection resolution mode. `true` = half resolution with bilinear
/// upsample in lighting.frag. `false` = full (native) resolution.
///
/// Half-res is a 4× reduction in ray trace invocations, SVGF denoiser
/// passes, and TAA resolve — the three costliest RT workloads.
///
///   Native 1080p: 2.07M rays + 5 × 2.07M SVGF + 2.07M TAA = ~14.5M invocations.
///   Half   1080p: 0.52M rays + 5 × 0.52M SVGF + 0.52M TAA = ~3.6M invocations.
///
/// Quality impact is minor with the current pipeline: 256² blue noise
/// provides sufficient spatial decorrelation at half resolution, SVGF
/// temporal + à-trous fully denoise the lower sample count, and the
/// lighting shader's bilinear sampler smoothly upsamples the result.
/// G-buffer depth/normal edge-stopping in the denoiser still operates
/// on full-res data (scaled coordinate lookups), preserving geometry
/// edges in the reflection signal.
pub const RT_HALF_RES: bool = true;

