/// Compute AO image dimensions. Returns `extent` when native, `extent/2`
/// when half-res (rounded up so odd resolutions don't lose a pixel row).
#[inline]
fn ao_resolution(extent: vk::Extent2D) -> vk::Extent2D {
    if AO_HALF_RES {
        vk::Extent2D {
            width: (extent.width + 1) / 2,
            height: (extent.height + 1) / 2,
        }
    } else {
        extent
    }
}

