/// Compute RT reflection image dimensions. Returns `extent / 2` (ceil'd)
/// when `RT_HALF_RES`, otherwise `extent` for native resolution. Used by
/// AccelContext init, resize recreation, and all RT compute dispatch sizing.
#[inline]
pub fn rt_resolution(extent: vk::Extent2D) -> vk::Extent2D {
    if RT_HALF_RES {
        vk::Extent2D {
            width:  (extent.width  + 1) / 2,
            height: (extent.height + 1) / 2,
        }
    } else {
        extent
    }
}
