    point_light_count: u32,      // number of active point lights
    csm_resolution: u32,         // CSM shadow map resolution (e.g. 2048)
    shadow_atlas_size: u32,      // shadow atlas dimension (e.g. 4096)
    billboard_flags: u32,        // Phase 4.7: bit 0 = skip shadow, bit 1 = skip AO
    ibl_strength: f32,           // Phase 4.9: IBL intensity multiplier
    fog_density: f32,            // Exponential density
    fog_height_falloff: f32,     // Height-based thinning (0 = uniform)
    fog_max_opacity: f32,        // Clamp [0..1]
    fog_color_start: [f32; 4],   // rgb = fog color, w = start_distance
    fog_horizon_power: f32,      // Horizon band sharpness exponent
    fog_horizon_opacity: f32,    // Sky horizon haze strength [0..1]
    shaft_contrast: f32,             // Shaft mask power curve (1.0=linear, >1=sharper)
