    sun_disk_size: f32,          // Step 0: angular radius in degrees
    sky_mode: u32,               // Step 0: 0=environment, 1=procedural
    debug_view_mode: u32,        // DebugViewMode discriminant (0=off)
    volumetrics_enabled: u32,    // 1 = froxel fog, 0 = analytical height fog

    fog_max_opacity: f32,        // Clamp [0..1]
    fog_color_start: [f32; 4],   // rgb = fog color, w = start_distance
    fog_horizon_power: f32,      // Horizon band sharpness exponent
    fog_horizon_opacity: f32,    // Sky horizon haze strength [0..1]
    shaft_contrast: f32,             // Shaft mask power curve (1.0=linear, >1=sharper)
    multi_bounce_factor: f32,    // Step 0: AO multi-bounce approx (0.0–0.25)
    sun_disk_size: f32,          // Step 0: angular radius in degrees
    sky_mode: u32,               // Step 0: 0=environment, 1=procedural
    debug_view_mode: u32,        // DebugViewMode discriminant (0=off)
