/// VkDrawIndexedIndirectCommand layout for shadow MDI.
///
/// Shadow passes render ALL objects (no camera frustum cull) via a single
/// `cmd_draw_indexed_indirect` per cascade/face, eliminating N individual
/// draw call overhead (~0.5–2μs each in driver).
///
/// `first_instance` = object index → `gl_BaseInstance` in vertex shader
/// for SSBO lookup of model matrix and skinning data.
#[repr(C)]
#[derive(Clone, Copy)]
struct ShadowIndirectCommand {
    index_count: u32,
    instance_count: u32,
    first_index: u32,
    vertex_offset: i32,
    first_instance: u32,
}

// Compile-time assertion: must match VkDrawIndexedIndirectCommand (20 bytes).
const _: () = assert!(std::mem::size_of::<ShadowIndirectCommand>() == INDIRECT_COMMAND_SIZE as usize);

/// Per-tile draw state for point shadow MDI with per-light culling.
///
/// Built each frame in draw_frame. Dirty tiles get filtered indirect
/// commands pushed to the ring buffer. Cached tiles are skipped entirely.
#[derive(Clone, Copy)]
struct PointShadowDrawInfo {
    /// Byte offset into ring buffer for this tile's filtered indirect commands.
    ring_offset: u64,
    /// Number of objects passing the light-sphere cull test.
    draw_count: u32,
    /// false = shadow map cached from previous frame, skip clear + render.
    is_dirty: bool,
}

/// Cached shadow state for a single point light.
///

    /// Byte offset into ring buffer for this tile's filtered indirect commands.
    ring_offset: u64,
    /// Number of objects passing the light-sphere cull test.
    draw_count: u32,
    /// false = shadow map cached from previous frame, skip clear + render.
    is_dirty: bool,
}

/// Cached shadow state for a single point light.
///
/// Enables frame-over-frame reuse of shadow maps for static lights.
/// Cache is invalidated when light position, radius, atlas assignment,
/// or nearby geometry changes.
#[derive(Clone, Copy)]
struct CachedShadowTile {
    /// Light position when shadow map was last rendered.
    position: glam::Vec3,
    /// Light radius when last rendered.
    radius: f32,
    /// Atlas offset when last rendered (allocation stability check).
    atlas_offset: (u32, u32),
    /// Face resolution when last rendered.
    face_resolution: u32,
}

