    dir_x: f32,   // 1.0 for H pass, 0.0 for V pass
    dir_y: f32,   // 0.0 for H pass, 1.0 for V pass
    ao_edge_sharpness: f32,
}

/// G-Buffer push constants — VT debug + heightmap self-shadow + tessellation.
