/// tess_max_level/tess_max_distance at offsets 24/28: TCS/TES + fragment PDO.
#[repr(C)]
#[derive(Clone, Copy)]
struct GbufferPushConstants {
    vt_debug_mode: u32,
    shadow_sun_dir: [f32; 3],
    shadow_strength: f32,
    tess_active: u32,
    tess_max_level: f32,
