/// Compute froxel grid dimensions for a given screen extent.
/// XY = ceil(screen / FROXEL_TILE_SIZE), Z = 64 (Tier 2+) or 32 (Tier 1).
fn compute_froxel_dims(extent: vk::Extent2D, z_slices: u32) -> [u32; 3] {
    [
        (extent.width + FROXEL_TILE_SIZE - 1) / FROXEL_TILE_SIZE,
        (extent.height + FROXEL_TILE_SIZE - 1) / FROXEL_TILE_SIZE,
        z_slices,
    ]
}

//  Hi-Z mip helpers

#[derive(Clone, Copy, Debug)]
struct HizMipDim {
    width: u32,
    height: u32,
}

fn compute_hiz_mip_dims(extent: vk::Extent2D) -> Vec<HizMipDim> {
    let mip_count = mip_levels_for_extent(extent);
    let mut dims = Vec::with_capacity(mip_count as usize);
    let mut w = extent.width;
    let mut h = extent.height;
    for _ in 0..mip_count {
        dims.push(HizMipDim { width: w, height: h });
        w = (w / 2).max(1);
        h = (h / 2).max(1);
    }
    dims
}

#[inline]
fn mip_levels_for_extent(extent: vk::Extent2D) -> u32 {
    ((extent.width.max(extent.height) as f32).log2().floor() as u32) + 1
}

/// Compute bounding sphere from AABB — center + half-diagonal radius.
/// Less tight than per-vertex computation but needs no vertex access.
#[inline]
fn bounding_sphere_from_aabb(aabb_min: [f32; 3], aabb_max: [f32; 3]) -> [f32; 4] {
    let cx = (aabb_min[0] + aabb_max[0]) * 0.5;
    let cy = (aabb_min[1] + aabb_max[1]) * 0.5;
    let cz = (aabb_min[2] + aabb_max[2]) * 0.5;
    let dx = aabb_max[0] - aabb_min[0];
    let dy = aabb_max[1] - aabb_min[1];
    let dz = aabb_max[2] - aabb_min[2];

/// Compute bounding sphere from AABB — center + half-diagonal radius.
/// Less tight than per-vertex computation but needs no vertex access.
#[inline]
fn bounding_sphere_from_aabb(aabb_min: [f32; 3], aabb_max: [f32; 3]) -> [f32; 4] {
    let cx = (aabb_min[0] + aabb_max[0]) * 0.5;
    let cy = (aabb_min[1] + aabb_max[1]) * 0.5;
    let cz = (aabb_min[2] + aabb_max[2]) * 0.5;
    let dx = aabb_max[0] - aabb_min[0];
    let dy = aabb_max[1] - aabb_min[1];
    let dz = aabb_max[2] - aabb_min[2];
    let radius = (dx * dx + dy * dy + dz * dz).sqrt() * 0.5;
    [cx, cy, cz, radius]
}

