// Subsequent placements: clone descriptors sharing the
// SAME VB/IB/material data (true instancing geometry sharing).
for placement in placements.iter().skip(1) {
    let inst_desc_start = procedural.meshes.len();

    // Clone each mesh descriptor from the first placement's
    // range, overriding only the transform.
    for mesh_i in 0..base_mesh_count {
        let src_desc = &procedural.meshes[desc_start + mesh_i];
        let mut new_desc = src_desc.clone();

        // Subsequent placements: clone descriptors sharing the
        // SAME VB/IB/material data (true instancing geometry sharing).
        for placement in placements.iter().skip(1) {
            let inst_desc_start = procedural.meshes.len();

            // Clone each mesh descriptor from the first placement's
            // range, overriding only the transform.
            for mesh_i in 0..base_mesh_count {
                let src_desc = &procedural.meshes[desc_start + mesh_i];
                let mut new_desc = src_desc.clone();

                // Apply this placement's world transform.
                // The src_desc already has the per-mesh local
                // transform baked in from the glTF. We need to
                // replace the first placement's world transform
                // with this placement's. Extract the local
                // transform by undoing the first placement's world:
                let first_world_inv = first.transform.inverse();
                let local_transform = first_world_inv * src_desc.transform;
                new_desc.transform = placement.transform * local_transform;

                // Override per-placement properties.
                new_desc.rt_reflections = placement.asset_def.rt_reflections;
                new_desc.emitter_shape =
                    placement.asset_def.emitter_shape.unwrap_or_default();
                new_desc.emitter_texture_path =
                    placement.asset_def.emitter_texture.clone();
                new_desc.emitter_occlusion = placement.asset_def.emitter_occlusion;
                new_desc.emitter_cast_shadow = placement.asset_def.emitter_cast_shadow;

                procedural.meshes.push(new_desc);
            }

            let inst_desc_count = base_mesh_count;

            // Sector registration for this instance.
            if !placement.asset_def.always_visible {
                if let Some(cell) = placement.asset_def.sector_cell(sector_size) {
                    named_ranges.push((inst_desc_start, inst_desc_count, cell));
                }
            }
            // All placements need collision registration via named_defs.
            named_defs.push((placement.name.clone(), placement.asset_def.clone()));

            println!(
                "[Renderer]   Instance '{}' at [{:.1}, {:.1}, {:.1}] (shared geometry)",
                placement.name,
                placement.asset_def.position.unwrap_or([0.0; 3])[0],
                placement.asset_def.position.unwrap_or([0.0; 3])[1],
                placement.asset_def.position.unwrap_or([0.0; 3])[2],
            );
        }
    }
}

