    // Build VT reference counts from assigned material VT IDs.
    // Shared VTs (from source image dedup) will have count > 1.
    for mat in &materials {
        if mat.vt_albedo_id != u32::MAX {
            *vt_refcounts_init.entry(mat.vt_albedo_id).or_insert(0u32) += 1;
        }
        if mat.vt_normal_id != u32::MAX {
            *vt_refcounts_init.entry(mat.vt_normal_id).or_insert(0u32) += 1;
        }
    }
    if !vt_refcounts_init.is_empty() {
        let shared = vt_refcounts_init.values().filter(|&&c| c > 1).count();
        println!("[VT] Refcounts: {} VT IDs tracked, {} shared", vt_refcounts_init.len(), shared);
    }

    // Upload source images to GPU for compute shader sampling.
    if let Err(e) = vt.upload_sources_to_gpu(
        &device, &mut mem, ctx.command_pool, ctx.graphics_queue,
    ) {
        eprintln!("[VT] GPU source upload failed (CPU fallback): {e}");
