// ── Lighting descriptor layout (Phase 1.6: 8 bindings) ──
//    0: albedo sampler (FRAGMENT)
//    1: normal+rough sampler (FRAGMENT)
//    2: depth sampler (FRAGMENT)
//    3: GlobalUBO dynamic (FRAGMENT) — ring buffer
//    4: PointLight SSBO dynamic (FRAGMENT) — ring buffer
//    5: CSM shadow map array + comparison sampler (FRAGMENT)
//    6: ShadowTileInfo SSBO (FRAGMENT) — per-tile face VPs + atlas rects
//    7: Point light shadow atlas + comparison sampler (FRAGMENT)
let lighting_desc_set_layout = {
    let bindings = [
        vk::DescriptorSetLayoutBinding::default()
            .binding(0)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(1)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT),
        vk::DescriptorSetLayoutBinding::default()
            .binding(1)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(1)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT),
        vk::DescriptorSetLayoutBinding::default()
            .binding(2)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(1)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT),
        vk::DescriptorSetLayoutBinding::default()
            .binding(3)
            .descriptor_type(vk::DescriptorType::UNIFORM_BUFFER_DYNAMIC)

            .descriptor_count(1)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT),
        // Phase 2 textured emitter plan: binding 27 is the
        // bindless pool of Gaussian-prefiltered emitter
        // textures. VARIABLE_DESCRIPTOR_COUNT + PARTIALLY_
        // BOUND semantics require this to be the HIGHEST
        // binding number in the set — all prior bindings
        // are fixed-count, this one alone is variable.
        vk::DescriptorSetLayoutBinding::default()
            .binding(27)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(crate::ltc_textures::MAX_TEXTURES as u32)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT),
    ];
    // Per-binding flags: all zero except binding 27, which
    // needs VARIABLE_DESCRIPTOR_COUNT + PARTIALLY_BOUND.
    // PARTIALLY_BOUND lets slot indices beyond the active
    // count remain unwritten without a validation error
    // (we do write the 1×1 dummy to every slot anyway, but
    // the flag also covers the not-yet-updated frame edge
    // case). The flags array MUST be the same length as
    // `bindings` with the variable-count flag on the entry
    // whose binding number is the highest — Vulkan spec
    // VUID-VkDescriptorSetLayoutBindingFlagsCreateInfo-
    // pBindingFlags-03004.
    let mut binding_flags = vec![
        vk::DescriptorBindingFlags::empty();
        bindings.len()
    ];
    *binding_flags.last_mut().unwrap() =
        vk::DescriptorBindingFlags::VARIABLE_DESCRIPTOR_COUNT
        | vk::DescriptorBindingFlags::PARTIALLY_BOUND;
    let mut flags_info =
        vk::DescriptorSetLayoutBindingFlagsCreateInfo::default()
            .binding_flags(&binding_flags);
    unsafe {
        device.create_descriptor_set_layout(
            &vk::DescriptorSetLayoutCreateInfo::default()
                .bindings(&bindings)
                .push_next(&mut flags_info),
            None,
        )?
    }
};

