// Uses grass_terrain_desc_range captured during the loading loop to
// extract ONLY the terrain asset's geometry — not the entire scene.
// loaded.vertices / loaded.indices still accessible (partial move —
// only animation_data, meshes, materials were moved out).
if let Some(ref attach_name) = grass_system.config.attach_to.clone() {
    if let Some((desc_start, desc_count)) = grass_terrain_desc_range {
        // Extract only the terrain asset's mesh descriptors.
        let terrain_descs = &mesh_descriptors[desc_start..desc_start + desc_count];

        let mut terrain_verts: Vec<Vertex> = Vec::new();
        let mut terrain_indices: Vec<u32> = Vec::new();
        let mut terrain_colors: Vec<[f32; 4]> = Vec::new();

        for desc in terrain_descs {
            let vo = desc.vertex_offset as usize;
            let vc = desc.vertex_count as usize;
            let io = desc.index_offset as usize;
            let ic = desc.index_count as usize;

            if vo + vc <= loaded.vertices.len()
                && io + ic <= loaded.indices.len()
            {
                let idx_base = terrain_verts.len() as u32;

                // Pre-transform vertices to world space using the
                // descriptor's full transform (asset_transform ×
                // glTF node_transform). This is the same transform
                // the GPU applies at draw time — ensures the raycast
                // surface exactly matches the rendered surface.
                let xform = desc.transform;
                let normal_mat = {
                    let inv = xform.inverse().transpose();
                    glam::Mat3::from_cols(
                        inv.col(0).truncate(),
                        inv.col(1).truncate(),
                        inv.col(2).truncate(),
                    )
                };
                for v in &loaded.vertices[vo..vo + vc] {
                    let world_pos = xform.transform_point3(
                        glam::Vec3::from(v.position),
                    );
                    let world_nrm = (normal_mat
                        * glam::Vec3::from(v.normal))
                        .normalize_or_zero();
                    terrain_verts.push(Vertex::new(
                        world_pos.into(),
                        world_nrm.into(),
                        v.uv,
                    ));

                    glam::Vec3::from(v.position),
                );
                let world_nrm = (normal_mat
                    * glam::Vec3::from(v.normal))
                    .normalize_or_zero();
                terrain_verts.push(Vertex::new(
                    world_pos.into(),
                    world_nrm.into(),
                    v.uv,
                ));
            }

            // Indices are 0-based local per primitive. Rebase
            // by idx_base for multi-descriptor concatenation.
            for &idx in &loaded.indices[io..io + ic] {
                terrain_indices.push(idx + idx_base);
            }

            // Extract vertex colors from the same vertex range.
            for vc_color in &loaded.vertex_colors[vo..vo + vc] {
                terrain_colors.push(*vc_color);
            }
        }
    }

    if !terrain_verts.is_empty() {
        println!(
            "[Grass] Building TerrainSampler from '{}': {} verts, {} indices ({} descriptors)",
            attach_name, terrain_verts.len(),
