        let sector_size = world_config_retained.as_ref()
            .map(|wc| wc.sector_size)
            .unwrap_or(25.0);
        let colors_ref = if terrain_colors.iter().any(|c| c[0] < 0.99) {
            Some(terrain_colors.as_slice())
        } else {
            None
        };
        let sampler = TerrainSampler::new(
            &terrain_verts,
            &terrain_indices,
            colors_ref,
            glam::Mat4::IDENTITY,
            sector_size,
        );
        grass_system.set_terrain(sampler);
    } else {
        println!(
            "[Grass] WARNING: terrain '{}' descriptors [{}, +{}) yielded no geometry",
            attach_name, desc_start, desc_count,
        );
    }
} else {
