    // Copy index data to staging.
    if let Some(ptr) = staging.mapped_ptr {
        unsafe {
            std::ptr::copy_nonoverlapping(
                decals::UNIT_CUBE_INDICES.as_ptr() as *const u8,
                ptr.as_ptr(),
                ib_size as usize,
            );
        }
    }
    let gpu_ib = mem.allocator.create_buffer(
        ib_size,
        vk::BufferUsageFlags::INDEX_BUFFER | vk::BufferUsageFlags::TRANSFER_DST,

            std::ptr::copy_nonoverlapping(
                decals::UNIT_CUBE_INDICES.as_ptr() as *const u8,
                ptr.as_ptr(),
                ib_size as usize,
            );
        }
    }
    let gpu_ib = mem.allocator.create_buffer(
        ib_size,
        vk::BufferUsageFlags::INDEX_BUFFER | vk::BufferUsageFlags::TRANSFER_DST,
        MemoryLocation::GpuOnly,
    )?;
    // One-shot copy.
    unsafe {
        let cmd_info = vk::CommandBufferAllocateInfo::default()
            .command_pool(ctx.command_pool)
            .level(vk::CommandBufferLevel::PRIMARY)
            .command_buffer_count(1);
        let cmd = device.allocate_command_buffers(&cmd_info)?[0];
        device.begin_command_buffer(
            cmd,
            &vk::CommandBufferBeginInfo::default()
                .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT),
        )?;
        device.cmd_copy_buffer(
            cmd, staging.buffer, gpu_ib.buffer,
            &[vk::BufferCopy::default().size(ib_size)],
        );
        device.end_command_buffer(cmd)?;
        device.queue_submit(
            ctx.graphics_queue,
            &[vk::SubmitInfo::default().command_buffers(&[cmd])],
            vk::Fence::null(),
        )?;
        device.queue_wait_idle(ctx.graphics_queue)?;
        device.free_command_buffers(ctx.command_pool, &[cmd]);
    }
    mem.allocator.free_buffer(staging.handle);
    gpu_ib
};

