/// Load a billboard atlas PNG from disk, decode to RGBA8, upload to
/// GPU via staging belt. Returns (ImageAllocation, width, height).
///
/// Uses R8G8B8A8_UNORM (not SRGB) — the billboard fragment shader
/// handles color math directly. Atlas may contain both color regions
/// and alpha masks that shouldn't go through hardware sRGB decode.
fn load_billboard_atlas(
    device: &Device,
    mem: &mut MemoryContext,
    ctx: &DeviceContext,
    path: &str,
) -> Result<(ImageAllocation, u32, u32), Box<dyn std::error::Error>> {
    // Decode PNG → RGBA8.
    let file = std::fs::File::open(path)
        .map_err(|e| format!("Failed to open billboard atlas '{}': {}", path, e))?;
    let reader = std::io::BufReader::new(file);
    let decoder = image::codecs::png::PngDecoder::new(reader)
        .map_err(|e| format!("Failed to decode billboard atlas PNG '{}': {}", path, e))?;
    let img = image::DynamicImage::from_decoder(decoder)
        .map_err(|e| format!("Failed to load billboard atlas '{}': {}", path, e))?;
    let (width, height) = img.dimensions();
    let rgba = img.to_rgba8();
    let pixels = rgba.as_raw();

    // Create GPU image.
    let gpu_image = mem.create_image(
        width, height,

        .map_err(|e| format!("Failed to decode billboard atlas PNG '{}': {}", path, e))?;
    let img = image::DynamicImage::from_decoder(decoder)
        .map_err(|e| format!("Failed to load billboard atlas '{}': {}", path, e))?;
    let (width, height) = img.dimensions();
    let rgba = img.to_rgba8();
    let pixels = rgba.as_raw();

    // Create GPU image.
    let gpu_image = mem.create_image(
        width, height,
        vk::Format::R8G8B8A8_SRGB,
        vk::ImageUsageFlags::SAMPLED | vk::ImageUsageFlags::TRANSFER_DST,
    )?;

    // Upload via staging belt → transitions to SHADER_READ_ONLY_OPTIMAL.
    mem.staging.upload_image_sync(
        pixels,
        gpu_image.image,
        vk::Extent3D { width, height, depth: 1 },
        vk::Format::R8G8B8A8_SRGB,
        vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
        ctx.command_pool,
        ctx.graphics_queue,
    )?;

    Ok((gpu_image, width, height))
}

/// Create a 1×1 white RGBA8 fallback texture for billboard atlas.
/// Used when no atlas path is specified or loading fails.
fn create_white_fallback_image(
    mem: &mut MemoryContext,
    ctx: &DeviceContext,
) -> Result<ImageAllocation, Box<dyn std::error::Error>> {
    let img = mem.create_image(
        1, 1, vk::Format::R8G8B8A8_SRGB,
        vk::ImageUsageFlags::SAMPLED | vk::ImageUsageFlags::TRANSFER_DST,
    )?;
    let white_pixel: [u8; 4] = [255, 255, 255, 255];
    mem.staging.upload_image_sync(
        &white_pixel,
        img.image,
        vk::Extent3D { width: 1, height: 1, depth: 1 },
        vk::Format::R8G8B8A8_SRGB,
        vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL,
        ctx.command_pool,
        ctx.graphics_queue,
    )?;
    Ok(img)
}

