        //   Fade-out: draw_dist*0.90 → draw_dist (scale 1→0)
        let geom_dist = cfg.effective_geometry_distance();
        let bb_fade_in_start = geom_dist * 0.80;
        let bb_fade_in_end = geom_dist * 0.95;
