        vk::PipelineStageFlags::COMPUTE_SHADER,
        vk::DependencyFlags::empty(), &[], &[barrier], &[],
    );
}

// ── Pass 2: Instance compact ─────────────────────────────
self.device.cmd_bind_pipeline(
    cmd, vk::PipelineBindPoint::COMPUTE,
    self.instance_compact_pipeline,
);
let compact_offsets = [instance_group_offset, instance_member_offset];
self.device.cmd_bind_descriptor_sets(
    cmd, vk::PipelineBindPoint::COMPUTE,
    self.instance_compact_pipeline_layout,
    0, &[self.instance_compact_desc_set], &compact_offsets,
);

let compact_pc: [u32; 2] = [total_groups, MAX_OBJECTS];
self.device.cmd_push_constants(
    cmd, self.instance_compact_pipeline_layout,
    vk::ShaderStageFlags::COMPUTE, 0,
    std::slice::from_raw_parts(
        compact_pc.as_ptr() as *const u8,
        std::mem::size_of::<[u32; 2]>(),
    ),
);

let compact_dispatch = (total_groups + 63) / 64;
self.device.cmd_dispatch(cmd, compact_dispatch, 1, 1);

// ── Barrier: compact writes → indirect draw + vertex read ─
{
    let indirect_barrier = vk::BufferMemoryBarrier::default()
        .buffer(self.indirect_buffer.buffer)
        .offset(0).size(INDIRECT_COMMAND_SIZE * MAX_OBJECTS as u64 * 2)
        .src_access_mask(vk::AccessFlags::SHADER_WRITE)
        .dst_access_mask(vk::AccessFlags::INDIRECT_COMMAND_READ);
    let counter_barrier = vk::BufferMemoryBarrier::default()
        .buffer(self.instance_counter_buffer.buffer)
        .offset(0).size(INSTANCE_COUNTER_BUFFER_SIZE)
        .src_access_mask(vk::AccessFlags::SHADER_WRITE)
        .dst_access_mask(
            vk::AccessFlags::INDIRECT_COMMAND_READ
                | vk::AccessFlags::TRANSFER_READ,
        );
    let remap_barrier = vk::BufferMemoryBarrier::default()
        .buffer(self.instance_remap_buffer.buffer)
        .offset(0).size(std::mem::size_of::<u32>() as u64 * MAX_OBJECTS as u64)
        .src_access_mask(vk::AccessFlags::SHADER_WRITE)
        .dst_access_mask(vk::AccessFlags::SHADER_READ);
    self.device.cmd_pipeline_barrier(
        cmd, vk::PipelineStageFlags::COMPUTE_SHADER,
        vk::PipelineStageFlags::DRAW_INDIRECT
            | vk::PipelineStageFlags::VERTEX_SHADER
            | vk::PipelineStageFlags::TRANSFER,
        vk::DependencyFlags::empty(), &[],
        &[indirect_barrier, counter_barrier, remap_barrier], &[],

            .offset(0).size(std::mem::size_of::<u32>() as u64 * MAX_OBJECTS as u64)
            .src_access_mask(vk::AccessFlags::SHADER_WRITE)
            .dst_access_mask(vk::AccessFlags::SHADER_READ);
        self.device.cmd_pipeline_barrier(
            cmd, vk::PipelineStageFlags::COMPUTE_SHADER,
            vk::PipelineStageFlags::DRAW_INDIRECT
                | vk::PipelineStageFlags::VERTEX_SHADER
                | vk::PipelineStageFlags::TRANSFER,
            vk::DependencyFlags::empty(), &[],
            &[indirect_barrier, counter_barrier, remap_barrier], &[],
        );
    }

    // Copy both draw counts (std + tess) from instance_counter_buffer → readback.
    {
        let stride = std::mem::size_of::<[u32; 2]>() as u64;
        let off = fi as u64 * stride;
        let region = vk::BufferCopy::default()
            .src_offset(0)    // std_draw_count + tess_draw_count are contiguous
            .dst_offset(off)
            .size(stride);
        self.device.cmd_copy_buffer(
            cmd, self.instance_counter_buffer.buffer,
            self.draw_count_readback.buffer,
            std::slice::from_ref(&region),
        );
    }
}

unsafe fn record_vt_feedback_clear(&self, cmd: vk::CommandBuffer) {
    if let Some(ref vt) = self.vt_manager {
        let clear_value = vk::ClearColorValue {
            uint32: [0xFFFF_FFFF, 0, 0, 0],
        };
        self.device.cmd_clear_color_image(
            cmd, vt.feedback.image.image,
            vk::ImageLayout::TRANSFER_DST_OPTIMAL,
            &clear_value,
            &[vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: 0, level_count: 1,
                base_array_layer: 0, layer_count: 1,
            }],
        );
    }
}

unsafe fn record_gbuffer(
    &self,
    cmd: vk::CommandBuffer,
    _fi: usize,
    object_count: u32,
    global_ubo_offset: u32,
    object_ssbo_offset: u32,
    joint_ssbo_offset: u32,
) {
    let color_attachments = [
        vk::RenderingAttachmentInfo::default()
            .image_view(self.gbuf_albedo.view)
            .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)

    _fi: usize,
    object_count: u32,
    global_ubo_offset: u32,
    object_ssbo_offset: u32,
    joint_ssbo_offset: u32,
) {
    let color_attachments = [
        vk::RenderingAttachmentInfo::default()
            .image_view(self.gbuf_albedo.view)
            .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .load_op(vk::AttachmentLoadOp::CLEAR)
            .store_op(vk::AttachmentStoreOp::STORE)
            .clear_value(vk::ClearValue {
                color: vk::ClearColorValue { float32: [0.0; 4] },
            }),
        vk::RenderingAttachmentInfo::default()
            .image_view(self.gbuf_normal_rough.view)
            .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .load_op(vk::AttachmentLoadOp::CLEAR)
            .store_op(vk::AttachmentStoreOp::STORE)
            .clear_value(vk::ClearValue {
                color: vk::ClearColorValue { float32: [0.0; 4] },
            }),
        // GBUF_EMISSIVE: clear to 0. Later G-buffer writers (grass,
        // billboards, decals) LOAD this so the mesh pass's emissive
        // values survive.
        vk::RenderingAttachmentInfo::default()
            .image_view(self.gbuf_emissive.view)
            .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .load_op(vk::AttachmentLoadOp::CLEAR)
            .store_op(vk::AttachmentStoreOp::STORE)
            .clear_value(vk::ClearValue {
                color: vk::ClearColorValue { float32: [0.0; 4] },
            }),
        // Phase 6.8a: instance ID — clear to 0xFFFFFFFF sentinel.
        // Pixels with no geometry keep the sentinel (sky, etc.).
        vk::RenderingAttachmentInfo::default()
            .image_view(self.gbuf_instance_id.view)
            .image_layout(vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL)
            .load_op(vk::AttachmentLoadOp::CLEAR)
            .store_op(vk::AttachmentStoreOp::STORE)
            .clear_value(vk::ClearValue {
                color: vk::ClearColorValue { uint32: [0xFFFFFFFFu32, 0, 0, 0] },
            }),
    ];
    let depth_attachment = vk::RenderingAttachmentInfo::default()
        .image_view(self.depth_image.view)
        .image_layout(vk::ImageLayout::DEPTH_ATTACHMENT_OPTIMAL)
        .load_op(vk::AttachmentLoadOp::CLEAR)
        .store_op(vk::AttachmentStoreOp::STORE)
        .clear_value(vk::ClearValue {
            depth_stencil: vk::ClearDepthStencilValue {
                depth: 0.0, stencil: 0,
            },
        });
    let rendering_info = vk::RenderingInfo::default()
        .render_area(vk::Rect2D {
            offset: vk::Offset2D { x: 0, y: 0 }, extent: self.extent,
        })
        .layer_count(1)

    .clear_value(vk::ClearValue {
        depth_stencil: vk::ClearDepthStencilValue {
            depth: 0.0, stencil: 0,
        },
    });
let rendering_info = vk::RenderingInfo::default()
    .render_area(vk::Rect2D {
        offset: vk::Offset2D { x: 0, y: 0 }, extent: self.extent,
    })
    .layer_count(1)
    .color_attachments(&color_attachments)
    .depth_attachment(&depth_attachment);

self.device.cmd_begin_rendering(cmd, &rendering_info);

// ── Draw 1: Standard pipeline (non-displaced objects) ─────
self.device.cmd_bind_pipeline(
    cmd, vk::PipelineBindPoint::GRAPHICS, self.gbuf_pipeline,
);
render_graph::cmd_fullscreen_viewport_scissor(&self.device, cmd, self.extent);
self.device.cmd_bind_vertex_buffers(
    cmd, 0, &[self.vertex_buffer.buffer], &[0],
);
self.device.cmd_bind_index_buffer(
    cmd, self.index_buffer.buffer, 0, vk::IndexType::UINT32,
);
let gbuf_offsets = [global_ubo_offset, object_ssbo_offset, joint_ssbo_offset];
self.device.cmd_bind_descriptor_sets(
    cmd, vk::PipelineBindPoint::GRAPHICS, self.gbuf_pipeline_layout,
    0, &[self.gbuf_desc_set], &gbuf_offsets,
);
self.device.cmd_bind_descriptor_sets(
    cmd, vk::PipelineBindPoint::GRAPHICS, self.gbuf_pipeline_layout,
    1, &[self.material_desc_set], &[],
);
// Bind set 2: Virtual Texture resources.
if let Some(ref vt) = self.vt_manager {
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS, self.gbuf_pipeline_layout,
        2, &[vt.desc_set], &[],
    );
}

// Standard path: tess_active=0, self-shadow + PDO active in fragment shader.
let sun_dir = self.atmosphere.sun_direction_towards_sun();
let gbuf_pc_std = GbufferPushConstants {
    vt_debug_mode: self.vt_debug_mode as u32,
    shadow_sun_dir: [sun_dir[0], sun_dir[1], sun_dir[2]],
    shadow_strength: 0.8,
    tess_active: 0,
    tess_max_level: 16.0,
    tess_max_distance: 15.0,
};
render_graph::cmd_push_constants(
    &self.device, cmd, self.gbuf_pipeline_layout,
    vk::ShaderStageFlags::FRAGMENT, &gbuf_pc_std,
);
// Standard draws: indirect buffer offset 0, count at counter byte offset 0.
self.device.cmd_draw_indexed_indirect_count(
    cmd, self.indirect_buffer.buffer, 0,

    tess_max_level: 16.0,
    tess_max_distance: 15.0,
};
render_graph::cmd_push_constants(
    &self.device, cmd, self.gbuf_pipeline_layout,
    vk::ShaderStageFlags::FRAGMENT, &gbuf_pc_std,
);
// Standard draws: indirect buffer offset 0, count at counter byte offset 0.
self.device.cmd_draw_indexed_indirect_count(
    cmd, self.indirect_buffer.buffer, 0,
    self.instance_counter_buffer.buffer, 0, // std_draw_count at byte offset 0
    MAX_OBJECTS, INDIRECT_COMMAND_SIZE as u32,
);

// ── Draw 2: Tessellation pipeline (displaced objects) ─────
if let (Some(tp), Some(tl)) = (self.gbuf_tess_pipeline, self.gbuf_tess_pipeline_layout) {
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::GRAPHICS, tp,
    );
    // Descriptor sets are layout-compatible at sets 0–2 (identical
    // set layouts, only push constant ranges differ). Re-bind with
    // the tess pipeline layout for correct push constant validation.
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS, tl,
        0, &[self.gbuf_desc_set], &gbuf_offsets,
    );
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS, tl,
        1, &[self.material_desc_set], &[],
    );
    if let Some(ref vt) = self.vt_manager {
        self.device.cmd_bind_descriptor_sets(
            cmd, vk::PipelineBindPoint::GRAPHICS, tl,
            2, &[vt.desc_set], &[],
        );
    }

    let gbuf_pc_tess = GbufferPushConstants {
        vt_debug_mode: self.vt_debug_mode as u32,
        shadow_sun_dir: [sun_dir[0], sun_dir[1], sun_dir[2]],
        shadow_strength: 0.8,
        tess_active: 1,
        tess_max_level: 16.0,
        tess_max_distance: 15.0,
    };
    render_graph::cmd_push_constants(
        &self.device, cmd, tl,
        vk::ShaderStageFlags::FRAGMENT
            | vk::ShaderStageFlags::TESSELLATION_CONTROL
            | vk::ShaderStageFlags::TESSELLATION_EVALUATION,
        &gbuf_pc_tess,
    );
    // Tess draws: indirect buffer at tess region, count at counter byte offset 4.
    let tess_indirect_offset = INDIRECT_COMMAND_SIZE * MAX_OBJECTS as u64;
    self.device.cmd_draw_indexed_indirect_count(
        cmd, self.indirect_buffer.buffer, tess_indirect_offset,
        self.instance_counter_buffer.buffer,
        std::mem::size_of::<u32>() as u64,   // tess_draw_count at byte offset 4
        MAX_OBJECTS, INDIRECT_COMMAND_SIZE as u32,
    );

            &gbuf_pc_tess,
        );
        // Tess draws: indirect buffer at tess region, count at counter byte offset 4.
        let tess_indirect_offset = INDIRECT_COMMAND_SIZE * MAX_OBJECTS as u64;
        self.device.cmd_draw_indexed_indirect_count(
            cmd, self.indirect_buffer.buffer, tess_indirect_offset,
            self.instance_counter_buffer.buffer,
            std::mem::size_of::<u32>() as u64,   // tess_draw_count at byte offset 4
            MAX_OBJECTS, INDIRECT_COMMAND_SIZE as u32,
        );
    }

    self.device.cmd_end_rendering(cmd);
}

unsafe fn record_vt_feedback_readback(&self, cmd: vk::CommandBuffer, fi: usize) {
    if let Some(ref vt) = self.vt_manager {
        if vt.has_active_vts() {
            vt.feedback.record_readback(&self.device, cmd, fi);
        }
    }
}

/// Point shadow render — batched single rendering scope.
///
/// All dirty faces across all tiles are rendered within a single
/// `begin_rendering` / `end_rendering` scope covering the full atlas.
/// Per-face clears use `cmd_clear_attachments` (respects scissor).
/// Eliminates 6N-1 rendering scope transitions.
///
/// Cached tiles (is_dirty == false) are skipped entirely — the atlas
/// retains their shadow map from the previous frame.
unsafe fn record_point_shadow_batched(
    &self,
    cmd: vk::CommandBuffer,
    tiles: &[ShadowAtlasTile],
    global_ubo_offset: u32,
    object_ssbo_offset: u32,
    joint_ssbo_offset: u32,
) {
    if tiles.is_empty() { return; }

    // Check if ALL tiles are cached — skip entire pass.
    let any_dirty = self.point_shadow_draw_infos.iter().any(|d| d.is_dirty);
    if !any_dirty { return; }

    // ── Tight render area over dirty tiles only ──────────────
    // Compute bounding rect of all dirty tile blocks to minimise
    // LOAD_OP_LOAD bandwidth. Cached tiles sit outside and are not
    // loaded/stored unnecessarily on tile-based GPUs.
    let mut ra_min_x = SHADOW_ATLAS_SIZE;
    let mut ra_min_y = SHADOW_ATLAS_SIZE;
    let mut ra_max_x = 0u32;
    let mut ra_max_y = 0u32;
    for (ti, tile) in tiles.iter().enumerate() {
        if !self.point_shadow_draw_infos.get(ti).map_or(false, |d| d.is_dirty) {
            continue;
        }
        let block_w = tile.face_resolution * 3;
        let block_h = tile.face_resolution * 2;

let mut ra_min_x = SHADOW_ATLAS_SIZE;
let mut ra_min_y = SHADOW_ATLAS_SIZE;
let mut ra_max_x = 0u32;
let mut ra_max_y = 0u32;
for (ti, tile) in tiles.iter().enumerate() {
    if !self.point_shadow_draw_infos.get(ti).map_or(false, |d| d.is_dirty) {
        continue;
    }
    let block_w = tile.face_resolution * 3;
    let block_h = tile.face_resolution * 2;
    ra_min_x = ra_min_x.min(tile.atlas_offset.0);
    ra_min_y = ra_min_y.min(tile.atlas_offset.1);
    ra_max_x = ra_max_x.max(tile.atlas_offset.0 + block_w);
    ra_max_y = ra_max_y.max(tile.atlas_offset.1 + block_h);
}
if ra_max_x <= ra_min_x || ra_max_y <= ra_min_y {
    return; // degenerate — no dirty tiles survived
}

let depth_attachment = vk::RenderingAttachmentInfo::default()
    .image_view(self.shadow_atlas.view)
    .image_layout(vk::ImageLayout::DEPTH_ATTACHMENT_OPTIMAL)
    .load_op(vk::AttachmentLoadOp::LOAD)
    .store_op(vk::AttachmentStoreOp::STORE);
let rendering_info = vk::RenderingInfo::default()
    .render_area(vk::Rect2D {
        offset: vk::Offset2D { x: ra_min_x as i32, y: ra_min_y as i32 },
        extent: vk::Extent2D {
            width: ra_max_x - ra_min_x,
            height: ra_max_y - ra_min_y,
        },
    })
    .layer_count(1)
    .depth_attachment(&depth_attachment);

self.device.cmd_begin_rendering(cmd, &rendering_info);

// Bind pipeline + shared state once.
self.device.cmd_bind_vertex_buffers(
    cmd, 0, &[self.vertex_buffer.buffer], &[0],
);
self.device.cmd_bind_index_buffer(
    cmd, self.index_buffer.buffer, 0, vk::IndexType::UINT32,
);
self.device.cmd_bind_pipeline(
    cmd, vk::PipelineBindPoint::GRAPHICS, self.point_shadow_res.pipeline,
);
let dynamic_offsets = [global_ubo_offset, object_ssbo_offset, joint_ssbo_offset];
self.device.cmd_bind_descriptor_sets(
    cmd, vk::PipelineBindPoint::GRAPHICS,
    self.point_shadow_res.pipeline_layout,
    0, &[self.point_shadow_desc_set], &dynamic_offsets,
);

// Clear value for per-face depth clear (1.0 = fully lit in standard Z).
let clear_attachment = vk::ClearAttachment {
    aspect_mask: vk::ImageAspectFlags::DEPTH,
    color_attachment: 0,
    clear_value: vk::ClearValue {
        depth_stencil: vk::ClearDepthStencilValue {

    self.point_shadow_res.pipeline_layout,
    0, &[self.point_shadow_desc_set], &dynamic_offsets,
);

// Clear value for per-face depth clear (1.0 = fully lit in standard Z).
let clear_attachment = vk::ClearAttachment {
    aspect_mask: vk::ImageAspectFlags::DEPTH,
    color_attachment: 0,
    clear_value: vk::ClearValue {
        depth_stencil: vk::ClearDepthStencilValue {
            depth: 1.0, stencil: 0,
        },
    },
};

for (tile_idx, tile) in tiles.iter().enumerate() {
    let draw_info = match self.point_shadow_draw_infos.get(tile_idx) {
        Some(di) => di,
        None => continue,
    };

    // Skip cached tiles — atlas retains their shadow data.
    if !draw_info.is_dirty { continue; }

    let light = &self.scene.lights[tile.light_index as usize];
    let face_matrices =
        Scene::point_light_shadow_matrices(light.position, light.radius);
    let face_res = tile.face_resolution;

    for face in 0..6u32 {
        let face_col = face % 3;
        let face_row = face / 3;
        let vp_x = tile.atlas_offset.0 + face_col * face_res;
        let vp_y = tile.atlas_offset.1 + face_row * face_res;

        // Set viewport + scissor to this face's region.
        let viewport = vk::Viewport {
            x: vp_x as f32, y: vp_y as f32,
            width: face_res as f32, height: face_res as f32,
            min_depth: 0.0, max_depth: 1.0,
        };
        self.device.cmd_set_viewport(cmd, 0, &[viewport]);

        let scissor = vk::Rect2D {
            offset: vk::Offset2D { x: vp_x as i32, y: vp_y as i32 },
            extent: vk::Extent2D { width: face_res, height: face_res },
        };
        self.device.cmd_set_scissor(cmd, 0, &[scissor]);

        // Clear this face's depth region (respects scissor).
        let clear_rect = vk::ClearRect {
            rect: scissor,
            base_array_layer: 0,
            layer_count: 1,
        };
        self.device.cmd_clear_attachments(
            cmd,
            std::slice::from_ref(&clear_attachment),
            std::slice::from_ref(&clear_rect),
        );

            let clear_rect = vk::ClearRect {
                rect: scissor,
                base_array_layer: 0,
                layer_count: 1,
            };
            self.device.cmd_clear_attachments(
                cmd,
                std::slice::from_ref(&clear_attachment),
                std::slice::from_ref(&clear_rect),
            );

            // Push face VP matrix.
            let face_pc = PointLightShadowPushConstants {
                view_proj: face_matrices[face as usize],
            };
            render_graph::cmd_push_constants(
                &self.device, cmd, self.point_shadow_res.pipeline_layout,
                vk::ShaderStageFlags::VERTEX, &face_pc,
            );

            // Indirect dispatch — guard with draw_count > 0 to skip the
            // (otherwise valid) zero-count call. The clear above already ran.
            if draw_info.draw_count > 0 {
                self.device.cmd_draw_indexed_indirect(
                    cmd,
                    self.memory_ctx.ring.buffer,
                    draw_info.ring_offset,
                    draw_info.draw_count,
                    INDIRECT_COMMAND_SIZE as u32,
                );
            }
        }
    }

    self.device.cmd_end_rendering(cmd);
}

// insert after record_hiz_downsample, before record_light_cull
// (~line 5922 of renderer.rs)

/// Phase 5.1: Per-pixel motion vectors from depth reprojection.
///
/// Compute dispatch on graphics queue (Submit 3). Reads depth buffer +
/// current/prev view_proj from GlobalUBO, writes R16G16_SFLOAT velocity.
/// 8×8 workgroups, full-resolution dispatch.
unsafe fn record_motion_vectors(
    &self,
    cmd: vk::CommandBuffer,
    global_ubo_offset: u32,
) {
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::COMPUTE, self.motion_vectors_res.pipeline,
    );
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::COMPUTE,
        self.motion_vectors_res.pipeline_layout,
        0, &[self.motion_vectors_desc_set],
        &[global_ubo_offset],
    );
    // S5: Push precomputed reprojection matrix.

    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::COMPUTE, self.motion_vectors_res.pipeline,
    );
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::COMPUTE,
        self.motion_vectors_res.pipeline_layout,
        0, &[self.motion_vectors_desc_set],
        &[global_ubo_offset],
    );
    // S5: Push precomputed reprojection matrix.
    let mv_pc = MotionVectorsPushConstants {
        reprojection: self.mv_reprojection,
    };
    render_graph::cmd_push_constants(
        &self.device, cmd, self.motion_vectors_res.pipeline_layout,
        vk::ShaderStageFlags::COMPUTE, &mv_pc,
    );
    // Dispatch: ceil(width/8) × ceil(height/8)
    let gx = (self.extent.width + 7) / 8;
    let gy = (self.extent.height + 7) / 8;
    self.device.cmd_dispatch(cmd, gx, gy, 1);

    // Execution barrier: motion vectors compute → downstream compute readers
    // (volumetric temporal, SSR temporal, irradiance cache hysteresis).
    // Image layout stays GENERAL (no transition), but we need a write→read
    // execution dependency for any pass that samples the velocity buffer.
    //
    // Currently no downstream consumer exists in the pass table yet — this
    // barrier is a no-op cost-wise but correct for when volumetrics/SSR land.
    // COMPUTE_SHADER-only dst stage: this CB runs on the dedicated compute
    // queue where FRAGMENT_SHADER is unsupported. The QFOT release at the
    // end of record_ao handles compute→graphics visibility.
    render_graph::barrier_compute_to_compute(&self.device, cmd);
}

/// Recompute sky atmosphere LUT if sun direction has changed.
///
/// Compares current sun_elevation + sun_rotation against cached values.
/// ~0.1ms when triggered, amortized to ~0 over stable frames.
unsafe fn maybe_recompute_sky_lut(&mut self, cmd: vk::CommandBuffer) {
    let atmos = &self.atmosphere;
    let current_sun = [atmos.sun_elevation, atmos.sun_rotation];

    // Check if sun has moved (or first frame)
    let changed = !self.sky_lut_valid
        || (current_sun[0] - self.sky_lut_cached_sun[0]).abs() > 0.01
        || (current_sun[1] - self.sky_lut_cached_sun[1]).abs() > 0.01;

    if !changed { return; }

    self.sky_lut_cached_sun = current_sun;
    self.sky_lut_valid = true;

    let sun_dir = atmos.sun_direction_towards_sun();

