/// Record volumetric scatter propagate compute dispatch.
///
/// Front-to-back Beer-Lambert integration along Z axis per XY thread.
/// Drop 2: dispatches stub (writes identity transmittance). Drop 3: full Beer-Lambert.
unsafe fn record_volumetric_propagate(
    &self,
