    global_ubo_offset: u32,
) {

/// Record volumetric scatter propagate compute dispatch.
///
/// Front-to-back Beer-Lambert integration along Z axis per XY thread.
/// Drop 2: dispatches stub (writes identity transmittance). Drop 3: full Beer-Lambert.
unsafe fn record_volumetric_propagate(
    &self,
    cmd: vk::CommandBuffer,
    fi: usize,
    global_ubo_offset: u32,
) {
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::COMPUTE, self.vol_propagate_res.pipeline,
    );
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::COMPUTE,
        self.vol_propagate_res.pipeline_layout,
        0, &[self.vol_propagate_desc_sets[fi]],
        &[global_ubo_offset],
    );

    let pc = VolumetricPropagatePushConstants {
        froxel_dims: [
            self.vol_froxel_dims[0],
            self.vol_froxel_dims[1],
            self.vol_froxel_dims[2],
            0,
        ],
        near: self.scene.camera.near,
        max_distance: self.atmosphere.volumetric_max_distance,
        temporal_blend: self.atmosphere.volumetric_temporal_blend,
        _pad: 0.0,
    };
    render_graph::cmd_push_constants(
        &self.device, cmd, self.vol_propagate_res.pipeline_layout,
        vk::ShaderStageFlags::COMPUTE, &pc,
    );

    // Dispatch: ceil(froxelX/8) × ceil(froxelY/8) × 1
    // Each thread walks all Z slices for its XY position.
    let gx = (self.vol_froxel_dims[0] + 7) / 8;
    let gy = (self.vol_froxel_dims[1] + 7) / 8;
    self.device.cmd_dispatch(cmd, gx, gy, 1);

    // Execution barrier: propagate write → downstream compute reads.
    // When called from record_vol_pre_chain (compute queue), FRAGMENT_SHADER
    // is invalid. Use compute-only barrier; cross-queue visibility is handled
    // by the QFOT release at the vol chain tail.
    render_graph::barrier_compute_to_compute(&self.device, cmd);
}

