    );
    let gx = (dim0.width + 15) / 16;
    let gy = (dim0.height + 15) / 16;
    self.device.cmd_dispatch(cmd, gx, gy, 1);

    // ── Barrier: copy write → SPD read ──────────────────────────
    render_graph::barrier_compute_to_compute(&self.device, cmd);

    // ── Pass 2: SPD bulk (mips 1–6, single dispatch) ────────────
    if self.hiz_mip_count > 1 {
        self.device.cmd_bind_pipeline(
            cmd, vk::PipelineBindPoint::COMPUTE, self.hiz_spd_pipeline,
        );
        let spd_pc = HizSpdPushConstants {
            src_width: dim0.width as i32,
            src_height: dim0.height as i32,
