            _pad: 0,
        };
        render_graph::cmd_push_constants(
            &self.device, cmd, self.hiz_spd_pipeline_layout,
            vk::ShaderStageFlags::COMPUTE, &spd_pc,
        );
        self.device.cmd_bind_descriptor_sets(
            cmd, vk::PipelineBindPoint::COMPUTE, self.hiz_spd_pipeline_layout,
            0, &[self.hiz_spd_desc_sets[fi]], &[],
        );
        // 64×64 tile per workgroup.
        let spd_gx = (dim0.width + 63) / 64;
        let spd_gy = (dim0.height + 63) / 64;
        self.device.cmd_dispatch(cmd, spd_gx, spd_gy, 1);

        // Barrier: SPD writes → serial tail reads.
        render_graph::barrier_compute_to_compute(&self.device, cmd);
    }

    // ── Pass 3+: Serial tail for mips 7+ (tiny images) ─────────
    // SPD handles mips 1–6. Existing shader handles 7+.
    let serial_start = 7.min(self.hiz_mip_count as usize);
    if serial_start < self.hiz_mip_count as usize {
        self.device.cmd_bind_pipeline(

        // Barrier: SPD writes → serial tail reads.
        render_graph::barrier_compute_to_compute(&self.device, cmd);
    }

    // ── Pass 3+: Serial tail for mips 7+ (tiny images) ─────────
    // SPD handles mips 1–6. Existing shader handles 7+.
    let serial_start = 7.min(self.hiz_mip_count as usize);
    if serial_start < self.hiz_mip_count as usize {
        self.device.cmd_bind_pipeline(
            cmd, vk::PipelineBindPoint::COMPUTE, self.hiz_pipeline,
        );
        for mip in serial_start..self.hiz_mip_count as usize {
            if mip > serial_start {
                render_graph::barrier_compute_to_compute(&self.device, cmd);
            }
            let dim = &self.hiz_mip_dims[mip];
            let pc = HizPushConstants {
                out_width: dim.width as i32,
                out_height: dim.height as i32,
                is_copy_pass: 0,
                _pad: 0,
            };
            render_graph::cmd_push_constants(
                &self.device, cmd, self.hiz_pipeline_layout,
                vk::ShaderStageFlags::COMPUTE, &pc,
            );
            self.device.cmd_bind_descriptor_sets(
                cmd, vk::PipelineBindPoint::COMPUTE, self.hiz_pipeline_layout,
                0, &[self.hiz_downsample_desc_sets[fi][mip]], &[],
            );
            let gx = (dim.width + 15) / 16;
            let gy = (dim.height + 15) / 16;
            self.device.cmd_dispatch(cmd, gx, gy, 1);
        }
    }

    // Final barrier: all Hi-Z writes → downstream reads.
    render_graph::barrier_compute_to_compute_and_fragment(&self.device, cmd);
}

// Per-frame world-space bounding sphere precomputation (zero-alloc).
// [OPT] Incremental: only recompute dynamic objects (skinned/physics).
// Static mesh bspheres recomputed on sector load/unload (world_bspheres.clear()).
fn precompute_world_bspheres(&mut self) {
    let n = self.mesh_descriptors.len();

    // Descriptor count changed (sector load/unload cleared vec) → full rebuild.
    if self.world_bspheres.len() != n {
        self.world_bspheres.clear();
        self.world_bspheres.reserve(n);
        for i in 0..n {
            self.world_bspheres.push(self.compute_world_bsphere(i));
        }
        return;
    }

    // Incremental: only recompute skinned + physics-driven objects.
    // Static objects retain bsphere from full rebuild.
    for i in 0..n {

        self.world_bspheres.reserve(n);
        for i in 0..n {
            self.world_bspheres.push(self.compute_world_bsphere(i));
        }
        return;
    }

    // Incremental: only recompute skinned + physics-driven objects.
    // Static objects retain bsphere from full rebuild.
    for i in 0..n {
        let desc = &self.mesh_descriptors[i];
        if desc.index_count == 0 {
            self.world_bspheres[i] = [0.0, 0.0, 0.0, 0.0];
            continue;
        }
        if desc.skin_index.is_some()
            || self.scene.is_physics_driven(i)
            || self.scene.is_transform_driven(i)
        {
            self.world_bspheres[i] = self.compute_world_bsphere(i);
        }
    }
}

/// Single bsphere: AABB → object-space sphere → world-space via transform.
#[inline]
fn compute_world_bsphere(&self, i: usize) -> [f32; 4] {
    let desc = &self.mesh_descriptors[i];
    if desc.index_count == 0 {
        return [0.0, 0.0, 0.0, 0.0];
    }
    let bs = bounding_sphere_from_aabb(desc.aabb_min, desc.aabb_max);
    let center_os = glam::Vec3::new(bs[0], bs[1], bs[2]);
    let center_ws = desc.transform.transform_point3(center_os);
    let sx_sq = desc.transform.x_axis.truncate().length_squared();
    let sy_sq = desc.transform.y_axis.truncate().length_squared();
    let sz_sq = desc.transform.z_axis.truncate().length_squared();
    let max_scale = sx_sq.max(sy_sq).max(sz_sq).sqrt();
    let radius_ws = bs[3] * max_scale;
    [center_ws.x, center_ws.y, center_ws.z, radius_ws]
}

