// Tiled light culling compute dispatch.
// Bins point lights into 16x16 screen tiles using shared memory depth reduction
// and cooperative frustum+depth testing. Output: per-tile light index list SSBO.
unsafe fn record_light_cull(
    &self,
    cmd: vk::CommandBuffer,
    fi: usize,
    global_ubo_offset: u32,
    lights_ssbo_offset: u32,
    light_count: u32,
) {
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::COMPUTE, self.light_cull_res.pipeline,
    );
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::COMPUTE,
        self.light_cull_res.pipeline_layout,
        0, &[self.light_cull_desc_sets[fi]],
        &[global_ubo_offset, lights_ssbo_offset],
    );
    let pc = LightCullPushConstants {
        light_count,
        tile_count_x: self.light_tile_count_x,
        tile_count_y: self.light_tile_count_y,
        // Phase 1 emitter plan: forwarded from the CPU-owned
        // EmitterSet so the cull shader knows how many records to
        // iterate. Zero disables the entire emitter cull branch.
        emitter_count: self.emitter_set.count,
    };
    render_graph::cmd_push_constants(
        &self.device, cmd, self.light_cull_res.pipeline_layout,
        vk::ShaderStageFlags::COMPUTE, &pc,
    );
    self.device.cmd_dispatch(
        cmd,
        self.light_tile_count_x,
        self.light_tile_count_y,
        1,
    );

    // SSBO write→read barrier: light cull compute → lighting fragment.
    render_graph::barrier_compute_to_fragment(&self.device, cmd);
}

