/// Generate mip chain for scene_color via blit cascade.
/// Called between lighting and composite passes for auto-exposure.
/// Each mip level is 2× downsampled from the previous via LINEAR blit.
/// The highest mip (1×1 or 2×2) approximates the average scene luminance.
unsafe fn record_scene_color_mip_gen(&self, cmd: vk::CommandBuffer, fi: usize) {
    let image = self.scene_color_images[fi].image;
    let mut mip_width = self.extent.width;
    let mut mip_height = self.extent.height;

    for mip in 1..self.scene_color_mip_count {
        let src_width = mip_width;
        let src_height = mip_height;
        mip_width = (mip_width / 2).max(1);
        mip_height = (mip_height / 2).max(1);

        // Transition mip-1 → TRANSFER_SRC
        let barrier_src = vk::ImageMemoryBarrier::default()
            .old_layout(if mip == 1 {
                vk::ImageLayout::COLOR_ATTACHMENT_OPTIMAL
            } else {
                vk::ImageLayout::TRANSFER_DST_OPTIMAL
            })
            .new_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
            .src_access_mask(if mip == 1 {
                vk::AccessFlags::COLOR_ATTACHMENT_WRITE
            } else {
                vk::AccessFlags::TRANSFER_WRITE
            })
            .dst_access_mask(vk::AccessFlags::TRANSFER_READ)
            .image(image)
            .subresource_range(vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: mip - 1,
                level_count: 1,
                base_array_layer: 0,
                layer_count: 1,
            });

        // Transition target mip → TRANSFER_DST
        let barrier_dst = vk::ImageMemoryBarrier::default()
            .old_layout(vk::ImageLayout::UNDEFINED)
            .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
            .src_access_mask(vk::AccessFlags::empty())
            .dst_access_mask(vk::AccessFlags::TRANSFER_WRITE)
            .image(image)
            .subresource_range(vk::ImageSubresourceRange {
                aspect_mask: vk::ImageAspectFlags::COLOR,
                base_mip_level: mip,
                level_count: 1,
                base_array_layer: 0,
                layer_count: 1,

    .new_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
    .src_access_mask(vk::AccessFlags::empty())
    .dst_access_mask(vk::AccessFlags::TRANSFER_WRITE)
    .image(image)
    .subresource_range(vk::ImageSubresourceRange {
        aspect_mask: vk::ImageAspectFlags::COLOR,
        base_mip_level: mip,
        level_count: 1,
        base_array_layer: 0,
        layer_count: 1,
    });

self.device.cmd_pipeline_barrier(
    cmd,
    vk::PipelineStageFlags::COLOR_ATTACHMENT_OUTPUT
        | vk::PipelineStageFlags::TRANSFER,
    vk::PipelineStageFlags::TRANSFER,
    vk::DependencyFlags::empty(),
    &[], &[], &[barrier_src, barrier_dst],
);

// Blit mip-1 → mip (2× downsample with LINEAR filter)
let blit_region = vk::ImageBlit {
    src_subresource: vk::ImageSubresourceLayers {
        aspect_mask: vk::ImageAspectFlags::COLOR,
        mip_level: mip - 1,
        base_array_layer: 0,
        layer_count: 1,
    },
    src_offsets: [
        vk::Offset3D { x: 0, y: 0, z: 0 },
        vk::Offset3D {
            x: src_width as i32,
            y: src_height as i32,
            z: 1,
        },
    ],
    dst_subresource: vk::ImageSubresourceLayers {
        aspect_mask: vk::ImageAspectFlags::COLOR,
        mip_level: mip,
        base_array_layer: 0,
        layer_count: 1,
    },
    dst_offsets: [
        vk::Offset3D { x: 0, y: 0, z: 0 },
        vk::Offset3D {
            x: mip_width as i32,
            y: mip_height as i32,
            z: 1,
        },
    ],
};

self.device.cmd_blit_image(
    cmd,
    image, vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
    image, vk::ImageLayout::TRANSFER_DST_OPTIMAL,
    &[blit_region],
    vk::Filter::LINEAR,
);

            ],
        };

        self.device.cmd_blit_image(
            cmd,
            image, vk::ImageLayout::TRANSFER_SRC_OPTIMAL,
            image, vk::ImageLayout::TRANSFER_DST_OPTIMAL,
            &[blit_region],
            vk::Filter::LINEAR,
        );
    }

    // Transition ALL mips → SHADER_READ_ONLY for composite sampling
    let final_barrier = vk::ImageMemoryBarrier::default()
        .old_layout(vk::ImageLayout::TRANSFER_SRC_OPTIMAL)
        .new_layout(vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL)
        .src_access_mask(vk::AccessFlags::TRANSFER_READ)
        .dst_access_mask(vk::AccessFlags::SHADER_READ)
        .image(image)
        .subresource_range(vk::ImageSubresourceRange {
            aspect_mask: vk::ImageAspectFlags::COLOR,
            base_mip_level: 0,
            level_count: self.scene_color_mip_count - 1,
            base_array_layer: 0,
            layer_count: 1,
        });

    let last_mip_barrier = vk::ImageMemoryBarrier::default()
        .old_layout(vk::ImageLayout::TRANSFER_DST_OPTIMAL)
        .new_layout(vk::ImageLayout::SHADER_READ_ONLY_OPTIMAL)
        .src_access_mask(vk::AccessFlags::TRANSFER_WRITE)
        .dst_access_mask(vk::AccessFlags::SHADER_READ)
        .image(image)
        .subresource_range(vk::ImageSubresourceRange {
            aspect_mask: vk::ImageAspectFlags::COLOR,
            base_mip_level: self.scene_color_mip_count - 1,
            level_count: 1,
            base_array_layer: 0,
            layer_count: 1,
        });

    self.device.cmd_pipeline_barrier(
        cmd,
        vk::PipelineStageFlags::TRANSFER,
        vk::PipelineStageFlags::FRAGMENT_SHADER,
        vk::DependencyFlags::empty(),
        &[], &[], &[final_barrier, last_mip_barrier],
    );
}

/// Update CPU-side adapted luminance for temporal EMA auto-exposure.
/// Called once per frame after composite recording.
fn update_adapted_luminance(&mut self) {
    let alpha = 0.95_f32;
    let target_lum = 0.18 / self.atmosphere.exposure.max(0.001);
    self.adapted_luminance = self.adapted_luminance * alpha + target_lum * (1.0 - alpha);
}

