unsafe fn record_billboards(
    &mut self,
    cmd: vk::CommandBuffer,
    global_ubo_offset: u32,
) {
    // Finalize billboard partitions (normal vs cross) and upload SSBO.
    self.billboard_manager.finalize();
    let bb_offset = match self.billboard_manager.upload(&mut self.memory_ctx.ring) {
        Some(off) => off,
        None => {
            self.bb_csm_ssbo_offset = 0;
            return; // no billboards this frame
        }
    };
    self.bb_csm_ssbo_offset = bb_offset as u32;

    // Begin rendering — same G-Buffer attachments, LOAD to preserve mesh pass.
    let color_attachments = render_graph::gbuf_color_attachments_load(
        self.gbuf_albedo.view, self.gbuf_normal_rough.view,
        self.gbuf_emissive.view, self.gbuf_instance_id.view,
    );
    let depth_attachment = render_graph::depth_attachment_load_store(
        self.depth_image.view,
    );
    let rendering_info = render_graph::rendering_info_fullscreen(
        self.extent, &color_attachments, &depth_attachment,
    );

    self.device.cmd_begin_rendering(cmd, &rendering_info);
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::GRAPHICS, self.billboard_pipeline,
    );

    // Viewport + scissor.
    render_graph::cmd_fullscreen_viewport_scissor(&self.device, cmd, self.extent);

    // Push constants.
    let view = self.scene.camera.get_view_matrix();
    let pc = BillboardPushConstants::from_view_matrix(
        &view,
        self.billboard_manager.settings.alpha_cutoff,
        self.billboard_manager.time,
    );
    render_graph::cmd_push_constants(
        &self.device, cmd, self.billboard_pipeline_layout,

    // Push constants.
    let view = self.scene.camera.get_view_matrix();
    let pc = BillboardPushConstants::from_view_matrix(
        &view,
        self.billboard_manager.settings.alpha_cutoff,
        self.billboard_manager.time,
    );
    render_graph::cmd_push_constants(
        &self.device, cmd, self.billboard_pipeline_layout,
        vk::ShaderStageFlags::VERTEX | vk::ShaderStageFlags::FRAGMENT,
        &pc,
    );

    // Bind descriptor sets:
    //   set 0: GlobalUBO + ObjectSSBO (reuse gbuffer set)
    //   set 1: Materials + bindless textures (reuse material set)
    //   set 2: Billboard SSBO (dynamic) + atlas sampler
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS,
        self.billboard_pipeline_layout,
        0,
        &[self.gbuf_desc_set, self.material_desc_set, self.billboard_desc_set],
        &[global_ubo_offset, 0, 0, bb_offset as u32],
    );

    // Draw normal billboards (6 verts/instance).
    if let Some(draw) = self.billboard_manager.normal_draw() {
        self.device.cmd_draw(
            cmd, draw.vertex_count, draw.instance_count,
            0, draw.first_instance,
        );
    }

    // Draw cross-pair billboards (12 verts/instance).
    if let Some(draw) = self.billboard_manager.cross_draw() {
        self.device.cmd_draw(
            cmd, draw.vertex_count, draw.instance_count,
            0, draw.first_instance,
        );
    }

    self.device.cmd_end_rendering(cmd);
}

