/// Only fires when camera moves to a new cell and new sectors generate.
unsafe fn upload_grass_sectors(
    &mut self,
    cmd: vk::CommandBuffer,
) {
    let pending = self.grass_system.pending_uploads();
    if pending.is_empty() { return; }

    // Collect upload info before borrowing staging mutably.
    let uploads: Vec<(usize, u64, Vec<u8>)> = pending.iter().filter_map(|upload| {

/// Only fires when camera moves to a new cell and new sectors generate.
unsafe fn upload_grass_sectors(
    &mut self,
    cmd: vk::CommandBuffer,
) {
    let pending = self.grass_system.pending_uploads();
    if pending.is_empty() { return; }

    // Collect upload info before borrowing staging mutably.
    let uploads: Vec<(usize, u64, Vec<u8>)> = pending.iter().filter_map(|upload| {
        let src_data = self.grass_system.sector_upload_data(upload.coord)?;
        let byte_size = upload.blade_count * std::mem::size_of::<grass::GpuGrassInstance>();
        let dst_offset = grass::GrassGpuPool::slot_byte_offset(upload.slot_index);
        let bytes = unsafe {
            std::slice::from_raw_parts(
                src_data.as_ptr() as *const u8,
                byte_size,
            )
        };
        Some((upload.slot_index, dst_offset, bytes.to_vec()))
    }).collect();

    self.grass_system.clear_pending_uploads();

    for (_slot, dst_offset, bytes) in &uploads {
        // Write to staging chunk — returns (staging_buffer, src_offset).
        let (staging_buf, src_offset) = match self.memory_ctx.staging.write(bytes) {
            Ok(r) => r,
            Err(e) => {
                eprintln!("[Grass] Staging write failed: {e}");
                continue;
            }
        };

        // Record staging → GPU-local pool copy.
        let region = vk::BufferCopy::default()
            .src_offset(src_offset)
            .dst_offset(*dst_offset)
            .size(bytes.len() as u64);
        self.device.cmd_copy_buffer(
            cmd,
            staging_buf,
            self.grass_sector_pool.buffer,
            std::slice::from_ref(&region),
        );
    }

    if !uploads.is_empty() {
        // Barrier: transfer writes → vertex shader reads.
        let barrier = vk::BufferMemoryBarrier::default()
            .buffer(self.grass_sector_pool.buffer)
            .offset(0)
            .size(vk::WHOLE_SIZE)
            .src_access_mask(vk::AccessFlags::TRANSFER_WRITE)
            .dst_access_mask(vk::AccessFlags::SHADER_READ);
        self.device.cmd_pipeline_barrier(
            cmd,
            vk::PipelineStageFlags::TRANSFER,
            vk::PipelineStageFlags::VERTEX_SHADER,
            vk::DependencyFlags::empty(),

            .buffer(self.grass_sector_pool.buffer)
            .offset(0)
            .size(vk::WHOLE_SIZE)
            .src_access_mask(vk::AccessFlags::TRANSFER_WRITE)
            .dst_access_mask(vk::AccessFlags::SHADER_READ);
        self.device.cmd_pipeline_barrier(
            cmd,
            vk::PipelineStageFlags::TRANSFER,
            vk::PipelineStageFlags::VERTEX_SHADER,
            vk::DependencyFlags::empty(),
            &[], &[barrier], &[],
        );
    }
}

