///
/// Per-pixel ray-marched directional sun scatter with CSM shadow sampling.
/// Full-resolution screen-space pass producing pixel-perfect god rays.
/// Runs after volumetric propagate, before lighting composite.
unsafe fn record_vol_sun_scatter(
    &self,
