    let pc = VolSunScatterPushConstants {
        sun_direction: [
            sun_dir[0], sun_dir[1], sun_dir[2],
            atmos.volumetric_sun_intensity,
        ],
        sun_color: [
            atmos.sun_color[0], atmos.sun_color[1], atmos.sun_color[2],
            self.frame_number as f32,
