//  Grass G-Buffer pass recorder

/// Record the grass G-Buffer pass.
unsafe fn record_grass(
    &mut self,
    cmd: vk::CommandBuffer,
    global_ubo_offset: u32,
) {
    if !self.grass_system.has_draws() { return; }

    // ── Upload new sector data (staging → GPU pool) ──────────
    // Most frames this is a no-op.
    self.upload_grass_sectors(cmd);

    // ── Write multi-draw indirect commands ───────────────────
    let draw_bytes = self.grass_system.draw_command_bytes();
    let draw_count = self.grass_system.draw_count();

    self.device.cmd_update_buffer(
        cmd,
        self.grass_indirect_buffer.buffer,
        0,
        draw_bytes,
    );

    // Barrier: transfer write → indirect read.
    {
        let barrier = vk::BufferMemoryBarrier::default()
            .buffer(self.grass_indirect_buffer.buffer)
            .offset(0)
            .size(draw_bytes.len() as u64)
            .src_access_mask(vk::AccessFlags::TRANSFER_WRITE)
            .dst_access_mask(vk::AccessFlags::INDIRECT_COMMAND_READ);
        self.device.cmd_pipeline_barrier(
            cmd,
            vk::PipelineStageFlags::TRANSFER,
            vk::PipelineStageFlags::DRAW_INDIRECT,
            vk::DependencyFlags::empty(),
            &[], &[barrier], &[],
        );
    }

    // ── Begin rendering (same G-Buffer attachments) ──────────

        self.device.cmd_pipeline_barrier(
            cmd,
            vk::PipelineStageFlags::TRANSFER,
            vk::PipelineStageFlags::DRAW_INDIRECT,
            vk::DependencyFlags::empty(),
            &[], &[barrier], &[],
        );
    }

    // ── Begin rendering (same G-Buffer attachments) ──────────
    let color_attachments = render_graph::gbuf_color_attachments_load(
        self.gbuf_albedo.view, self.gbuf_normal_rough.view,
        self.gbuf_emissive.view, self.gbuf_instance_id.view,
    );
    let depth_attachment = render_graph::depth_attachment_load_store(
        self.depth_image.view,
    );
    let rendering_info = render_graph::rendering_info_fullscreen(
        self.extent, &color_attachments, &depth_attachment,
    );

    self.device.cmd_begin_rendering(cmd, &rendering_info);
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::GRAPHICS, self.grass_res.pipeline,
    );

    render_graph::cmd_fullscreen_viewport_scissor(&self.device, cmd, self.extent);

    let pc = self.grass_system.push_constants();
    render_graph::cmd_push_constants(
        &self.device, cmd, self.grass_res.pipeline_layout,
        vk::ShaderStageFlags::VERTEX | vk::ShaderStageFlags::FRAGMENT,
        &pc,
    );

    // Descriptor sets — set 2 now points at grass_sector_pool.
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS,
        self.grass_res.pipeline_layout,
        0,
        &[self.gbuf_desc_set, self.material_desc_set, self.grass_desc_set],
        &[global_ubo_offset, 0, 0, 0],
    );

    // ── Multi-draw indirect: one draw per visible sector ─────
    self.device.cmd_draw_indirect(
        cmd,
        self.grass_indirect_buffer.buffer,
        0,
        draw_count,
        16, // stride = sizeof(VkDrawIndirectCommand)
    );

    self.device.cmd_end_rendering(cmd);
}

