//  Phase 5: Decal pass recording

/// Record the deferred decal pass.
///
/// Rasterizes oriented unit cubes per-decal instance. Fragment shader
/// reconstructs world position from depth, projects into decal OBB,
/// samples atlas, alpha-blends into G-Buffer albedo + normal.
unsafe fn record_decals(
    &mut self,
    cmd: vk::CommandBuffer,
    global_ubo_offset: u32,
) {
    // ── Update attached decals from current body transforms ──
    // Must run after scene.sync_dynamic_bodies() has written
    // Jolt positions into descriptor_transforms. The render graph
    // calls scene.update() before draw_frame(), so transforms are current.
    self.decal_manager.update_attached_decals(&self.scene.descriptor_transforms);

    let decal_count = self.decal_manager.active_count();
    if decal_count == 0 {
        return;
    }

    // Upload decal SSBO to ring buffer.
    let decal_offset = match self.decal_manager.upload(&mut self.memory_ctx.ring) {
        Some(off) => off,
        None => return,
    };

    // Begin rendering — same G-Buffer attachments, LOAD to preserve mesh + billboard data.
    let color_attachments = render_graph::gbuf_color_attachments_load(
        self.gbuf_albedo.view, self.gbuf_normal_rough.view,
        self.gbuf_emissive.view, self.gbuf_instance_id.view,
    );
    // Depth attachment: read-only for depth testing + fragment shader sampling.
    // DEPTH_READ_ONLY_OPTIMAL allows simultaneous depth test and texelFetch.
    // Depth write is OFF in the pipeline — decals are screen-space projections.
    let depth_attachment = render_graph::depth_attachment_readonly(
        self.depth_image.view,
    );
    let rendering_info = render_graph::rendering_info_fullscreen(
        self.extent, &color_attachments, &depth_attachment,
    );

    self.device.cmd_begin_rendering(cmd, &rendering_info);
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::GRAPHICS, self.decal_pipeline,
    );

    // Viewport + scissor.
    render_graph::cmd_fullscreen_viewport_scissor(&self.device, cmd, self.extent);

    // Push constants.
    let pc = DecalPushConstants {

    self.device.cmd_begin_rendering(cmd, &rendering_info);
    self.device.cmd_bind_pipeline(
        cmd, vk::PipelineBindPoint::GRAPHICS, self.decal_pipeline,
    );

    // Viewport + scissor.
    render_graph::cmd_fullscreen_viewport_scissor(&self.device, cmd, self.extent);

    // Push constants.
    let pc = DecalPushConstants {
        total_decals: decal_count,
        _pad: [0; 3],
    };
    render_graph::cmd_push_constants(
        &self.device, cmd, self.decal_pipeline_layout,
        vk::ShaderStageFlags::VERTEX | vk::ShaderStageFlags::FRAGMENT,
        &pc,
    );

    // Bind descriptor sets — all decal-owned, no gbuf reuse.
    //   set 0: decal_ubo_desc_set — GlobalUBO (1 dynamic offset)
    //   set 1: decal_depth_desc_set — depth texture (0 dynamic offsets)
    //   set 2: decal_desc_set — Decal SSBO + atlas (1 dynamic offset)
    self.device.cmd_bind_descriptor_sets(
        cmd, vk::PipelineBindPoint::GRAPHICS,
        self.decal_pipeline_layout,
        0,
        &[self.decal_ubo_desc_set, self.decal_depth_desc_set, self.decal_desc_set],
        &[global_ubo_offset, decal_offset as u32],
    );

    // Bind unit cube index buffer.
    self.device.cmd_bind_index_buffer(
        cmd, self.decal_index_buffer.buffer, 0, vk::IndexType::UINT16,
    );

    // Draw: 36 indices per unit cube × N decal instances.
    self.device.cmd_draw_indexed(
        cmd,
        decals::UNIT_CUBE_INDEX_COUNT,  // 36
        decal_count,                     // instance count
        0, 0, 0,
    );

    self.device.cmd_end_rendering(cmd);
}

