/// Advance the peel cursor to the next pass. Returns (name, enabled).
pub fn advance_peel_target(&mut self) -> (&'static str, bool) {
    self.peel_target_index = (self.peel_target_index + 1)
        % render_graph::pass_flags::COUNT as u32;
    self.peel_target_info()
}

/// Toggle the pass at the current peel cursor.
pub fn toggle_peel_target(&mut self) {
    let flag = 1u32 << self.peel_target_index;
    self.toggle_pass(flag);
}

/// Current peel target (name, enabled).
pub fn peel_target_info(&self) -> (&'static str, bool) {
    let idx = self.peel_target_index as usize;
    let name = render_graph::pass_flags::NAMES[idx];
    let enabled = self.pass_enabled(1 << idx);
    (name, enabled)
}

