//  G-Buffer image allocation

fn create_gbuffer_images(
    mem: &mut MemoryContext,
    extent: vk::Extent2D,
) -> Result<(ImageAllocation, ImageAllocation, ImageAllocation, ImageAllocation, ImageAllocation), Box<dyn std::error::Error>> {
    let albedo = mem.create_image(
        extent.width, extent.height, GBUF_ALBEDO_FORMAT,
        vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::SAMPLED,
    )?;
    let normal_rough = mem.create_image(
        extent.width, extent.height, GBUF_NORMAL_ROUGH_FORMAT,
        vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::SAMPLED,
    )?;
    let emissive = mem.create_image(
        extent.width, extent.height, GBUF_EMISSIVE_FORMAT,
        vk::ImageUsageFlags::COLOR_ATTACHMENT | vk::ImageUsageFlags::SAMPLED,
    )?;
    // Phase 6.8a: instance ID for any-hit self-skip.
    let instance_id = mem.create_image(
        extent.width, extent.height, render_graph::GBUF_INSTANCE_ID_FORMAT,
        vk::ImageUsageFlags::COLOR_ATTACHMENT
            | vk::ImageUsageFlags::STORAGE
            | vk::ImageUsageFlags::SAMPLED
            | vk::ImageUsageFlags::TRANSFER_DST,
    )?;
    let depth = mem.create_image(
        extent.width, extent.height, DEPTH_FORMAT,
        vk::ImageUsageFlags::DEPTH_STENCIL_ATTACHMENT | vk::ImageUsageFlags::SAMPLED,
    )?;
    println!("[Renderer] G-Buffer: {}x{} (albedo/normal/emissive/instanceId+depth)",
             extent.width, extent.height);
    Ok((albedo, normal_rough, emissive, instance_id, depth))
}

/// Resolve RT reflection view + sampler for lighting binding 17.
/// Returns (view, sampler) — dummy black when RT is disabled.
/// Half-res RT uses a LINEAR sampler for smooth bilinear upsample
/// in lighting.frag; at native res NEAREST is used for exact fetch.
fn rt_reflect_binding(&self) -> (vk::ImageView, vk::Sampler) {
    if let Some(ref accel) = self.accel_ctx {
        let sampler = if RT_HALF_RES {
            // LINEAR + CLAMP_TO_EDGE for bilinear upsample of half-
            // res RT output. Reuses the volumetric scatter upsample

/// Resolve RT reflection view + sampler for lighting binding 17.
/// Returns (view, sampler) — dummy black when RT is disabled.
/// Half-res RT uses a LINEAR sampler for smooth bilinear upsample
/// in lighting.frag; at native res NEAREST is used for exact fetch.
fn rt_reflect_binding(&self) -> (vk::ImageView, vk::Sampler) {
    if let Some(ref accel) = self.accel_ctx {
        let sampler = if RT_HALF_RES {
            // LINEAR + CLAMP_TO_EDGE for bilinear upsample of half-
            // res RT output. Reuses the volumetric scatter upsample
            // sampler — same filtering requirements.
            self.vol_scatter_upsample_sampler
        } else {
            self.gbuf_sampler
        };
        (accel.rt_denoised_image.view, sampler)
    } else {
        (self.rt_dummy_black_image.view, self.rt_dummy_black_sampler)
    }
}

