    vt_desc_set_layout: Option<vk::DescriptorSetLayout>,
    _swapchain_format: vk::Format,
) -> Result<(vk::Pipeline, vk::PipelineLayout), Box<dyn std::error::Error>> {
    let frag_spv: &[u8] = if vt_desc_set_layout.is_some() {
        include_bytes!("../shaders/compiled/gbuffer_vt.frag.spv")
    } else {
        include_bytes!("../shaders/compiled/gbuffer.frag.spv")
    };
    let blend_attachments = [
        vk::PipelineColorBlendAttachmentState::default()
            .color_write_mask(vk::ColorComponentFlags::RGBA).blend_enable(false),
        vk::PipelineColorBlendAttachmentState::default()
            .color_write_mask(vk::ColorComponentFlags::RGBA).blend_enable(false),
        // GBUF_EMISSIVE: RGB-only write (no alpha in R11G11B10).
        vk::PipelineColorBlendAttachmentState::default()
            .color_write_mask(
                vk::ColorComponentFlags::R
                    | vk::ColorComponentFlags::G
                    | vk::ColorComponentFlags::B,
            )
            .blend_enable(false),
        // Phase 6.8a: GBUF_INSTANCE_ID (R32_UINT) — R-only write.
        vk::PipelineColorBlendAttachmentState::default()
            .color_write_mask(vk::ColorComponentFlags::R)
            .blend_enable(false),
    ];
    let color_fmts = [
        GBUF_ALBEDO_FORMAT,
        GBUF_NORMAL_ROUGH_FORMAT,
        GBUF_EMISSIVE_FORMAT,
        render_graph::GBUF_INSTANCE_ID_FORMAT,
    ];
    let push_ranges = [vk::PushConstantRange {
        stage_flags: vk::ShaderStageFlags::FRAGMENT,
        offset: 0,
        size: std::mem::size_of::<GbufferPushConstants>() as u32,
    }];
    let mut set_layouts = vec![desc_set_layout, material_desc_set_layout];
    if let Some(vt_layout) = vt_desc_set_layout {
        set_layouts.push(vt_layout);
    }
    GraphicsPipelineDesc::new(include_bytes!("../shaders/compiled/gbuffer.vert.spv"))
        .frag(frag_spv)
        .blend_attachments(&blend_attachments)
        .color_formats(&color_fmts)
        .set_layouts(&set_layouts)
        .push_constant_ranges(&push_ranges)
        .build(device)
}

