/// Create tessellation wireframe overlay pipeline.
///
/// Same TCS/TES stages as the tessellation gbuffer pipeline to produce
/// identical tessellated geometry. PolygonMode::LINE renders edges only.
/// Single color attachment (swapchain format) with alpha blending.
/// Depth read-only (GREATER_OR_EQUAL for reverse-Z) so wireframe is
/// properly occluded by closer geometry but does not write depth.
/// Shares pipeline layout with gbuf_tess_pipeline (identical descriptor
/// sets and push constant ranges).
fn create_tess_wireframe_pipeline(
    device: &Device, desc_set_layout: vk::DescriptorSetLayout,
    material_desc_set_layout: vk::DescriptorSetLayout,
    vt_desc_set_layout: Option<vk::DescriptorSetLayout>,
    swapchain_format: vk::Format,
) -> Result<(vk::Pipeline, vk::PipelineLayout), Box<dyn std::error::Error>> {
    let blend = [vk::PipelineColorBlendAttachmentState::default()
        .blend_enable(true)
        .src_color_blend_factor(vk::BlendFactor::SRC_ALPHA)
        .dst_color_blend_factor(vk::BlendFactor::ONE_MINUS_SRC_ALPHA)
        .color_blend_op(vk::BlendOp::ADD)
        .src_alpha_blend_factor(vk::BlendFactor::ONE)
        .dst_alpha_blend_factor(vk::BlendFactor::ZERO)
        .alpha_blend_op(vk::BlendOp::ADD)
        .color_write_mask(vk::ColorComponentFlags::RGBA)];
    let color_fmts = [swapchain_format];
    let push_ranges = [vk::PushConstantRange {
        stage_flags: vk::ShaderStageFlags::FRAGMENT
            | vk::ShaderStageFlags::TESSELLATION_CONTROL
            | vk::ShaderStageFlags::TESSELLATION_EVALUATION,
        offset: 0,
        size: std::mem::size_of::<GbufferPushConstants>() as u32,
    }];
    let mut set_layouts = vec![desc_set_layout, material_desc_set_layout];
    if let Some(vt_layout) = vt_desc_set_layout {
        set_layouts.push(vt_layout);
    }

        stage_flags: vk::ShaderStageFlags::FRAGMENT
            | vk::ShaderStageFlags::TESSELLATION_CONTROL
            | vk::ShaderStageFlags::TESSELLATION_EVALUATION,
        offset: 0,
        size: std::mem::size_of::<GbufferPushConstants>() as u32,
    }];
    let mut set_layouts = vec![desc_set_layout, material_desc_set_layout];
    if let Some(vt_layout) = vt_desc_set_layout {
        set_layouts.push(vt_layout);
    }
    GraphicsPipelineDesc::new(
        include_bytes!("../shaders/compiled/gbuffer_tess.vert.spv"),
    )
        .frag(include_bytes!("../shaders/compiled/tess_wireframe.frag.spv"))
        .tesc(include_bytes!("../shaders/compiled/gbuffer.tesc.spv"))
        .tese(include_bytes!("../shaders/compiled/gbuffer.tese.spv"))
        .patch_control_points(3)
        .polygon_mode(vk::PolygonMode::LINE)
        .cull_mode(vk::CullModeFlags::NONE)
        .depth_read_only(vk::CompareOp::GREATER_OR_EQUAL)
        .blend_attachments(&blend)
        .color_formats(&color_fmts)
        .set_layouts(&set_layouts)
        .push_constant_ranges(&push_ranges)
        .build(device)
}

/// Create descriptor set layout for material SSBO + bindless textures (set 1).
/// Uses variable descriptor count for the texture array.
fn create_material_desc_set_layout(
    device: &Device,
    max_textures: u32,
) -> Result<vk::DescriptorSetLayout, Box<dyn std::error::Error>> {
    let bindings = [
        // binding 0: MaterialGpu SSBO
        vk::DescriptorSetLayoutBinding::default()
            .binding(0)
            .descriptor_type(vk::DescriptorType::STORAGE_BUFFER)
            .descriptor_count(1)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT | vk::ShaderStageFlags::TESSELLATION_CONTROL | vk::ShaderStageFlags::TESSELLATION_EVALUATION),
        // binding 1: bindless texture array
        vk::DescriptorSetLayoutBinding::default()
            .binding(1)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(max_textures)
            .stage_flags(vk::ShaderStageFlags::FRAGMENT | vk::ShaderStageFlags::TESSELLATION_CONTROL | vk::ShaderStageFlags::TESSELLATION_EVALUATION),
    ];

    // Enable variable descriptor count + partially bound for binding 1.
    let binding_flags = [
        vk::DescriptorBindingFlags::empty(),
        vk::DescriptorBindingFlags::VARIABLE_DESCRIPTOR_COUNT
            | vk::DescriptorBindingFlags::PARTIALLY_BOUND
            | vk::DescriptorBindingFlags::UPDATE_AFTER_BIND,
    ];
    let mut flags_info = vk::DescriptorSetLayoutBindingFlagsCreateInfo::default()
        .binding_flags(&binding_flags);

    let layout = unsafe {
        device.create_descriptor_set_layout(

        vk::DescriptorBindingFlags::empty(),
        vk::DescriptorBindingFlags::VARIABLE_DESCRIPTOR_COUNT
            | vk::DescriptorBindingFlags::PARTIALLY_BOUND
            | vk::DescriptorBindingFlags::UPDATE_AFTER_BIND,
    ];
    let mut flags_info = vk::DescriptorSetLayoutBindingFlagsCreateInfo::default()
        .binding_flags(&binding_flags);

    let layout = unsafe {
        device.create_descriptor_set_layout(
            &vk::DescriptorSetLayoutCreateInfo::default()
                .bindings(&bindings)
                .flags(vk::DescriptorSetLayoutCreateFlags::UPDATE_AFTER_BIND_POOL)
                .push_next(&mut flags_info),
            None,
        )?
    };

    Ok(layout)
}

