fn create_debug_line_pipeline(
    device: &Device,
    swapchain_format: vk::Format,
) -> Result<(vk::Pipeline, vk::PipelineLayout), Box<dyn std::error::Error>> {
    let push_range = vk::PushConstantRange::default()
        .stage_flags(vk::ShaderStageFlags::VERTEX).offset(0)
        .size(64);
    let debug_attrs = [
        vk::VertexInputAttributeDescription::default()
            .binding(0).location(0)
            .format(vk::Format::R32G32B32_SFLOAT).offset(0),
        vk::VertexInputAttributeDescription::default()
            .binding(0).location(1)
            .format(vk::Format::R32G32B32A32_SFLOAT).offset(12),
    ];
    let blend = [vk::PipelineColorBlendAttachmentState::default()
        .blend_enable(true)
        .src_color_blend_factor(vk::BlendFactor::SRC_ALPHA)
        .dst_color_blend_factor(vk::BlendFactor::ONE_MINUS_SRC_ALPHA)
        .color_blend_op(vk::BlendOp::ADD)
        .src_alpha_blend_factor(vk::BlendFactor::ONE)
        .dst_alpha_blend_factor(vk::BlendFactor::ZERO)
        .alpha_blend_op(vk::BlendOp::ADD)
        .color_write_mask(vk::ColorComponentFlags::RGBA)];
    let color_fmts = [swapchain_format];
    GraphicsPipelineDesc::new(include_bytes!("../shaders/compiled/debug_line.vert.spv"))
        .frag(include_bytes!("../shaders/compiled/debug_line.frag.spv"))
        .vertex_stride(std::mem::size_of::<DebugLineVertex>() as u32)
        .vertex_attributes(&debug_attrs)
        .topology(vk::PrimitiveTopology::LINE_LIST)
        .cull_mode(vk::CullModeFlags::NONE)
        .no_depth_test()
        .blend_attachments(&blend)
        .color_formats(&color_fmts)
        .push_constant_ranges(std::slice::from_ref(&push_range))
        .build(device)
}

