/// One-shot transition of all Hi-Z images to GENERAL layout.
fn init_hiz_layouts(
    device: &Device,
    command_pool: vk::CommandPool,
    queue: vk::Queue,
    hiz_images: &[ImageAllocation],
    mip_count: u32,
) -> Result<(), Box<dyn std::error::Error>> {
    unsafe {
        let cmd = device.allocate_command_buffers(
            &vk::CommandBufferAllocateInfo::default()
                .command_pool(command_pool)
                .level(vk::CommandBufferLevel::PRIMARY)
                .command_buffer_count(1),
        )?[0];

        device.begin_command_buffer(cmd,
            &vk::CommandBufferBeginInfo::default()
                .flags(vk::CommandBufferUsageFlags::ONE_TIME_SUBMIT),
        )?;

        for img in hiz_images {
            Self::transition_image_mips(
                device, cmd, img.image,
                vk::ImageLayout::UNDEFINED, vk::ImageLayout::GENERAL,
                vk::AccessFlags::empty(),
                vk::AccessFlags::SHADER_READ | vk::AccessFlags::SHADER_WRITE,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::COMPUTE_SHADER,
                vk::ImageAspectFlags::COLOR, 0, mip_count,
            );
        }

        device.end_command_buffer(cmd)?;

                vk::ImageLayout::UNDEFINED, vk::ImageLayout::GENERAL,
                vk::AccessFlags::empty(),
                vk::AccessFlags::SHADER_READ | vk::AccessFlags::SHADER_WRITE,
                vk::PipelineStageFlags::TOP_OF_PIPE,
                vk::PipelineStageFlags::COMPUTE_SHADER,
                vk::ImageAspectFlags::COLOR, 0, mip_count,
            );
        }

        device.end_command_buffer(cmd)?;
        let fence = device.create_fence(&vk::FenceCreateInfo::default(), None)?;
        device.queue_submit(
            queue,
            &[vk::SubmitInfo::default().command_buffers(&[cmd])],
            fence,
        )?;
        device.wait_for_fences(&[fence], true, u64::MAX)?;
        device.destroy_fence(fence, None);
        device.free_command_buffers(command_pool, &[cmd]);
    }
    Ok(())
}

/// Create the unified descriptor pool and all Hi-Z descriptor sets:
/// - hiz_downsample_desc_sets[slot][mip] for serial tail passes
/// - hiz_spd_desc_sets[slot] for SPD bulk pass (mips 1–6)
/// - cull_hiz_desc_sets[slot] for the cull shader's Hi-Z read
fn create_hiz_descriptor_resources(
    device: &Device,
    ds_layout: vk::DescriptorSetLayout,        // serial downsample set layout
    spd_layout: vk::DescriptorSetLayout,        // SPD set layout (7 storage images)
    cull_hiz_layout: vk::DescriptorSetLayout,   // cull set 1 layout
    mip_count: u32,
    depth_image: &ImageAllocation,
    hiz_images: &[ImageAllocation],
    hiz_mip_views: &[Vec<vk::ImageView>],
    depth_sampler: vk::Sampler,
    hiz_sampler: vk::Sampler,
) -> Result<(
    vk::DescriptorPool,
    Vec<Vec<vk::DescriptorSet>>,   // serial downsample sets [slot][mip]
    Vec<vk::DescriptorSet>,         // SPD sets [slot]
    Vec<vk::DescriptorSet>,         // cull Hi-Z sets [slot]
), Box<dyn std::error::Error>>
{
    let n = MAX_FRAMES_IN_FLIGHT as u32;
    let ds_set_count = n * mip_count;       // serial downsample sets
    let spd_set_count = n;                   // SPD sets
    let cull_set_count = n;                  // cull Hi-Z sets
    let total_sets = ds_set_count + spd_set_count + cull_set_count;

    let pool_sizes = [
        // Serial downsample: 1 sampler/set. Cull: 1 sampler/set.
        vk::DescriptorPoolSize::default()
            .ty(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .descriptor_count(ds_set_count + cull_set_count),
        // Serial downsample: 2 storage/set. SPD: 7 storage/set.
        vk::DescriptorPoolSize::default()
            .ty(vk::DescriptorType::STORAGE_IMAGE)
            .descriptor_count(ds_set_count * 2 + spd_set_count * 7),

let pool_sizes = [
    // Serial downsample: 1 sampler/set. Cull: 1 sampler/set.
    vk::DescriptorPoolSize::default()
        .ty(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
        .descriptor_count(ds_set_count + cull_set_count),
    // Serial downsample: 2 storage/set. SPD: 7 storage/set.
    vk::DescriptorPoolSize::default()
        .ty(vk::DescriptorType::STORAGE_IMAGE)
        .descriptor_count(ds_set_count * 2 + spd_set_count * 7),
];
let pool = unsafe {
    device.create_descriptor_pool(
        &vk::DescriptorPoolCreateInfo::default()
            .pool_sizes(&pool_sizes)
            .max_sets(total_sets),
        None,
    )?
};

// ── Allocate serial downsample sets: [slot][mip] ────────
let mut ds_sets = Vec::with_capacity(MAX_FRAMES_IN_FLIGHT);
for _ in 0..MAX_FRAMES_IN_FLIGHT {
    let layouts: Vec<vk::DescriptorSetLayout> =
        (0..mip_count).map(|_| ds_layout).collect();
    let sets = unsafe {
        device.allocate_descriptor_sets(
            &vk::DescriptorSetAllocateInfo::default()
                .descriptor_pool(pool)
                .set_layouts(&layouts),
        )?
    };
    ds_sets.push(sets);
}

// ── Allocate SPD sets: [slot] ───────────────────────────
let spd_layouts: Vec<vk::DescriptorSetLayout> =
    (0..MAX_FRAMES_IN_FLIGHT).map(|_| spd_layout).collect();
let spd_sets = unsafe {
    device.allocate_descriptor_sets(
        &vk::DescriptorSetAllocateInfo::default()
            .descriptor_pool(pool)
            .set_layouts(&spd_layouts),
    )?
};

// ── Allocate cull Hi-Z sets: [slot] ─────────────────────
let cull_layouts: Vec<vk::DescriptorSetLayout> =
    (0..MAX_FRAMES_IN_FLIGHT).map(|_| cull_hiz_layout).collect();
let cull_sets = unsafe {
    device.allocate_descriptor_sets(
        &vk::DescriptorSetAllocateInfo::default()
            .descriptor_pool(pool)
            .set_layouts(&cull_layouts),
    )?
};

// ── Write serial downsample descriptors (unchanged) ─────
for slot in 0..MAX_FRAMES_IN_FLIGHT {
    for mip in 0..mip_count as usize {

    device.allocate_descriptor_sets(
        &vk::DescriptorSetAllocateInfo::default()
            .descriptor_pool(pool)
            .set_layouts(&cull_layouts),
    )?
};

// ── Write serial downsample descriptors (unchanged) ─────
for slot in 0..MAX_FRAMES_IN_FLIGHT {
    for mip in 0..mip_count as usize {
        let depth_info = vk::DescriptorImageInfo::default()
            .sampler(depth_sampler)
            .image_view(depth_image.view)
            .image_layout(vk::ImageLayout::DEPTH_READ_ONLY_OPTIMAL);

        let in_mip_idx = if mip == 0 { 0 } else { mip - 1 };
        let in_mip_info = vk::DescriptorImageInfo::default()
            .image_view(hiz_mip_views[slot][in_mip_idx])
            .image_layout(vk::ImageLayout::GENERAL);

        let out_mip_info = vk::DescriptorImageInfo::default()
            .image_view(hiz_mip_views[slot][mip])
            .image_layout(vk::ImageLayout::GENERAL);

        let writes = [
            vk::WriteDescriptorSet::default()
                .dst_set(ds_sets[slot][mip]).dst_binding(0)
                .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
                .image_info(std::slice::from_ref(&depth_info)),
            vk::WriteDescriptorSet::default()
                .dst_set(ds_sets[slot][mip]).dst_binding(1)
                .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                .image_info(std::slice::from_ref(&in_mip_info)),
            vk::WriteDescriptorSet::default()
                .dst_set(ds_sets[slot][mip]).dst_binding(2)
                .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                .image_info(std::slice::from_ref(&out_mip_info)),
        ];
        unsafe { device.update_descriptor_sets(&writes, &[]); }
    }
}

// ── Write SPD descriptors ───────────────────────────────
// binding 0: mip 0 (readonly src), bindings 1–6: mips 1–6 (writeonly dst)
for slot in 0..MAX_FRAMES_IN_FLIGHT {
    let num_spd_mips = 7.min(mip_count as usize); // mips 0–6
    let mut writes = Vec::with_capacity(num_spd_mips);
    // We need to keep DescriptorImageInfo alive for the writes.
    // Pre-build all infos, then build writes referencing them.
    let infos: Vec<vk::DescriptorImageInfo> = (0..num_spd_mips)
        .map(|m| {
            vk::DescriptorImageInfo::default()
                .image_view(hiz_mip_views[slot][m])
                .image_layout(vk::ImageLayout::GENERAL)
        })
        .collect();

    for (binding, info) in infos.iter().enumerate() {
        writes.push(
            vk::WriteDescriptorSet::default()

            .map(|m| {
                vk::DescriptorImageInfo::default()
                    .image_view(hiz_mip_views[slot][m])
                    .image_layout(vk::ImageLayout::GENERAL)
            })
            .collect();

        for (binding, info) in infos.iter().enumerate() {
            writes.push(
                vk::WriteDescriptorSet::default()
                    .dst_set(spd_sets[slot])
                    .dst_binding(binding as u32)
                    .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                    .image_info(std::slice::from_ref(info)),
            );
        }
        // If mip_count < 7, bind mip 0 view as dummy for unused bindings.
        // Prevents validation errors from unwritten descriptors.
        for binding in num_spd_mips..7 {
            writes.push(
                vk::WriteDescriptorSet::default()
                    .dst_set(spd_sets[slot])
                    .dst_binding(binding as u32)
                    .descriptor_type(vk::DescriptorType::STORAGE_IMAGE)
                    .image_info(std::slice::from_ref(&infos[0])),
            );
        }
        unsafe { device.update_descriptor_sets(&writes, &[]); }
    }

    // ── Write cull Hi-Z descriptors (unchanged) ─────────────
    for slot in 0..MAX_FRAMES_IN_FLIGHT {
        let hiz_info = vk::DescriptorImageInfo::default()
            .sampler(hiz_sampler)
            .image_view(hiz_images[slot].view)
            .image_layout(vk::ImageLayout::GENERAL);

        let write = vk::WriteDescriptorSet::default()
            .dst_set(cull_sets[slot]).dst_binding(0)
            .descriptor_type(vk::DescriptorType::COMBINED_IMAGE_SAMPLER)
            .image_info(std::slice::from_ref(&hiz_info));

        unsafe { device.update_descriptor_sets(&[write], &[]); }
    }

    Ok((pool, ds_sets, spd_sets, cull_sets))
}

