/// Register scene textures as virtual textures with VtMode-aware routing.
///
/// Uses `vt_routing` (built during named asset loading) to determine
/// per-material VT mode:
///   - **Prepacked**: VtSourceRefs::Prepacked — tiles read from disk,
///     NO source images stored in CPU RAM.  Manifest is read to
///     determine the disk-local VT index for each packed format.
///   - **Runtime**: VtSourceRefs::Runtime — source images stored,
///     CPU-side packing + compression per page fault.
///   - **Bindless**: Skipped entirely — no VT involvement.
///
/// Materials not covered by any routing entry (character mesh,
/// procedural geometry) default to Runtime.
fn register_scene_vts(
    vt_manager: &mut VirtualTextureManager,
    device: &Device,
    mem: &mut MemoryContext,
    materials: &mut [MaterialData],
    images: &[ImageData],
    vt_routing: &[MaterialVtRouting],
    command_pool: vk::CommandPool,
    queue: vk::Queue,
) -> Result<(), Box<dyn std::error::Error>> {
    use std::collections::HashMap;
    use crate::virtual_texture::VtSourceRefs;
    use crate::world::VtMode;

    // ── Build per-material routing lookup ──
    // Carries (vt_mode, vt_path, asset_path, img_base) per material.

    vt_routing: &[MaterialVtRouting],
    command_pool: vk::CommandPool,
    queue: vk::Queue,
) -> Result<(), Box<dyn std::error::Error>> {
    use std::collections::HashMap;
    use crate::virtual_texture::VtSourceRefs;
    use crate::world::VtMode;

    // ── Build per-material routing lookup ──
    // Carries (vt_mode, vt_path, asset_path, img_base) per material.
    // Materials not covered by any routing entry default to Runtime
    // with empty asset_path (character meshes, procedural geometry).
    struct MatRoute {
        mode: VtMode,
        vt_path: Option<String>,
        asset_path: String,
        img_base: usize,
    }
    let mut mat_route: Vec<MatRoute> = (0..materials.len())
        .map(|_| MatRoute {
            mode: VtMode::Runtime,
            vt_path: None,
            asset_path: String::new(),
            img_base: 0,
        })
        .collect();
    for route in vt_routing {
        for i in route.mat_start..(route.mat_start + route.mat_count) {
            if i < mat_route.len() {
                mat_route[i] = MatRoute {
                    mode: route.vt_mode,
                    vt_path: route.vt_path.clone(),
                    asset_path: route.asset_path.clone(),
                    img_base: route.img_base,
                };
            }
        }
    }

    // ── 0. Read manifests for prepacked assets ──
    let mut manifest_cache: HashMap<String, Vec<(prepack::VtManifestEntry, String)>> =
        HashMap::new();
    for route in vt_routing {
        if route.vt_mode == VtMode::Prepacked {
            if let Some(ref vt_path) = route.vt_path {
                if !manifest_cache.contains_key(vt_path) {
                    let manifest_file = std::path::Path::new(vt_path).join("manifest.vtm");
                    match prepack::read_manifest(&manifest_file) {
                        Ok((_header, entries)) => {
                            println!(
                                "[VT] Read manifest '{}': {} VT entries",
                                manifest_file.display(), entries.len(),
                            );
                            manifest_cache.insert(vt_path.clone(), entries);
                        }
                        Err(e) => {
                            eprintln!(
                                "[VT] Failed to read manifest '{}': {}",
                                manifest_file.display(), e,
                            );

                            "[VT] Read manifest '{}': {} VT entries",
                            manifest_file.display(), entries.len(),
                        );
                        manifest_cache.insert(vt_path.clone(), entries);
                    }
                    Err(e) => {
                        eprintln!(
                            "[VT] Failed to read manifest '{}': {}",
                            manifest_file.display(), e,
                        );
                    }
                }
            }
        }
    }
}

fn find_disk_vt_index(
    entries: &[(prepack::VtManifestEntry, String)],
    packed_format: VtPackedFormat,
) -> Option<u32> {
    let target = match packed_format {
        VtPackedFormat::AlbedoMetallic => 0u32,
        VtPackedFormat::NormalRoughnessEmissive => 1u32,
    };
    entries.iter().position(|(e, _)| e.packed_format == target)
        .map(|i| i as u32)
}

// ══════════════════════════════════════════════════════════
//  1. Store unique source images — dedup by (asset_path, local_idx)
//
//  Key change: instead of keying on the MERGED image index
//  (which differs per instance of the same glTF), we key on
//  (asset file path, image index within that file).
//
//  14 copies of utility_box_02_4k.gltf all have the same
//  internal texture indices (0,1,2) → same key → ONE copy stored.
//  Memory: 3.3GB → ~500MB. Compression work: 14× reduction.
// ══════════════════════════════════════════════════════════

// Maps (asset_path, local_image_index) → VT source_images index.
let mut img_to_source: HashMap<(String, u32), usize> = HashMap::new();
// Also track merged_idx → source_id for lookups during VT registration.
let mut merged_to_source: HashMap<u32, usize> = HashMap::new();

for (mi, mat) in materials.iter().enumerate() {
    let rt = &mat_route[mi];
    if rt.mode != VtMode::Runtime {
        continue;
    }

    for &merged_idx in &[
        mat.base_color_texture_index,
        mat.metallic_roughness_texture_index,
        mat.normal_texture_index,
    ] {
        if merged_idx == u32::MAX || (merged_idx as usize) >= images.len() {
            continue;
        }

    }

    for &merged_idx in &[
        mat.base_color_texture_index,
        mat.metallic_roughness_texture_index,
        mat.normal_texture_index,
    ] {
        if merged_idx == u32::MAX || (merged_idx as usize) >= images.len() {
            continue;
        }

        // Compute the index within the original glTF file.
        let local_idx = merged_idx - rt.img_base as u32;
        let dedup_key = (rt.asset_path.clone(), local_idx);

        if let Some(&existing_source) = img_to_source.get(&dedup_key) {
            // Source image already stored from another instance of
            // the same asset — just map the merged index to it.
            merged_to_source.insert(merged_idx, existing_source);
        } else {
            let img = &images[merged_idx as usize];
            let source_id = vt_manager.store_source_image(
                &img.pixels, img.width, img.height,
            );
            img_to_source.insert(dedup_key, source_id);
            merged_to_source.insert(merged_idx, source_id);
        }
    }
}

// ══════════════════════════════════════════════════════════
//  2. Register VTs per unique source combination
//
//  Dedup keys now use (asset_path, local_bc, local_mr) for Runtime,
//  so all 14 boxes share ONE albedo VT and ONE normal VT.
// ══════════════════════════════════════════════════════════

// Key: (mode, asset_path, local_bc_or_disk_idx, local_mr_idx)
let mut albedo_vts: HashMap<(VtMode, String, u32, u32), u32> = HashMap::new();
let mut normal_vts: HashMap<(VtMode, String, u32, u32), u32> = HashMap::new();

for (mi, mat) in materials.iter_mut().enumerate() {
    let rt = &mat_route[mi];

    if rt.mode == VtMode::Bindless {
        continue;
    }

    let img_base = rt.img_base as u32;

    // ── AlbedoMetallic VT ──
    let bc_idx = mat.base_color_texture_index;
    if bc_idx != u32::MAX && (bc_idx as usize) < images.len() {
        let mr_idx = mat.metallic_roughness_texture_index;

        let (key, disk_idx) = match rt.mode {
            VtMode::Prepacked => {
                let disk_idx = rt.vt_path.as_ref()
                    .and_then(|p| manifest_cache.get(p))
                    .and_then(|entries| find_disk_vt_index(entries, VtPackedFormat::AlbedoMetallic))

// ── AlbedoMetallic VT ──
let bc_idx = mat.base_color_texture_index;
if bc_idx != u32::MAX && (bc_idx as usize) < images.len() {
    let mr_idx = mat.metallic_roughness_texture_index;

    let (key, disk_idx) = match rt.mode {
        VtMode::Prepacked => {
            let disk_idx = rt.vt_path.as_ref()
                .and_then(|p| manifest_cache.get(p))
                .and_then(|entries| find_disk_vt_index(entries, VtPackedFormat::AlbedoMetallic))
                .unwrap_or(0);
            ((rt.mode, rt.asset_path.clone(), disk_idx, 0), disk_idx)
        }
        _ => {
            let local_bc = bc_idx - img_base;
            let local_mr = if mr_idx != u32::MAX { mr_idx - img_base } else { u32::MAX };
            ((rt.mode, rt.asset_path.clone(), local_bc, local_mr), 0)
        }
    };

    let vt_id = if let Some(&existing) = albedo_vts.get(&key) {
        existing
    } else {
        let img = &images[bc_idx as usize];
        let source_path = match rt.mode {
            VtMode::Prepacked => format!(
                "prepacked:albedo[disk_vt={}]", disk_idx,
            ),
            _ => format!(
                "runtime:albedo[{}+mr{}]", bc_idx, mr_idx,
            ),
        };
        let refs = match rt.mode {
            VtMode::Prepacked => VtSourceRefs::Prepacked {
                base_path: rt.vt_path.clone().unwrap_or_default(),
                disk_vt_index: disk_idx,
            },
            _ => VtSourceRefs::Runtime {
                base_color: merged_to_source.get(&bc_idx).copied(),
                metallic_roughness: if mr_idx != u32::MAX {
                    merged_to_source.get(&mr_idx).copied()
                } else {
                    None
                },
                normal: None,
                emissive: None,
            },
        };
        let id = vt_manager.register_virtual_texture(
            device, mem,
            source_path,
            img.width, img.height,
            VtPackedFormat::AlbedoMetallic,
            refs,
            command_pool, queue,
        )?;
        println!(
            "[VT] Registered AlbedoMetallic VT {} ({}x{}) mode={:?}{}",
            id, img.width, img.height, rt.mode,
            if rt.mode == VtMode::Prepacked {

            source_path,
            img.width, img.height,
            VtPackedFormat::AlbedoMetallic,
            refs,
            command_pool, queue,
        )?;
        println!(
            "[VT] Registered AlbedoMetallic VT {} ({}x{}) mode={:?}{}",
            id, img.width, img.height, rt.mode,
            if rt.mode == VtMode::Prepacked {
                format!(" disk_vt={}", disk_idx)
            } else {
                format!(" bc={} mr={}", bc_idx,
                    if mr_idx != u32::MAX { mr_idx.to_string() } else { "none".into() })
            },
        );
        albedo_vts.insert(key, id);
        id
    };
    mat.vt_albedo_id = vt_id;
}

// ── NormalRoughness VT ──
let nm_idx = mat.normal_texture_index;
if nm_idx != u32::MAX && (nm_idx as usize) < images.len() {
    let mr_idx = mat.metallic_roughness_texture_index;

    let (key, disk_idx) = match rt.mode {
        VtMode::Prepacked => {
            let disk_idx = rt.vt_path.as_ref()
                .and_then(|p| manifest_cache.get(p))
                .and_then(|entries| find_disk_vt_index(entries, VtPackedFormat::NormalRoughnessEmissive))
                .unwrap_or(1);
            ((rt.mode, rt.asset_path.clone(), disk_idx, 0), disk_idx)
        }
        _ => {
            let local_nm = nm_idx - img_base;
            let local_mr = if mr_idx != u32::MAX { mr_idx - img_base } else { u32::MAX };
            ((rt.mode, rt.asset_path.clone(), local_nm, local_mr), 0)
        }
    };

    let vt_id = if let Some(&existing) = normal_vts.get(&key) {
        existing
    } else {
        let img = &images[nm_idx as usize];
        let source_path = match rt.mode {
            VtMode::Prepacked => format!(
                "prepacked:normal[disk_vt={}]", disk_idx,
            ),
            _ => format!(
                "runtime:normal[{}+mr{}]", nm_idx, mr_idx,
            ),
        };
        let refs = match rt.mode {
            VtMode::Prepacked => VtSourceRefs::Prepacked {
                base_path: rt.vt_path.clone().unwrap_or_default(),
                disk_vt_index: disk_idx,
            },
            _ => VtSourceRefs::Runtime {

                _ => format!(
                    "runtime:normal[{}+mr{}]", nm_idx, mr_idx,
                ),
            };
            let refs = match rt.mode {
                VtMode::Prepacked => VtSourceRefs::Prepacked {
                    base_path: rt.vt_path.clone().unwrap_or_default(),
                    disk_vt_index: disk_idx,
                },
                _ => VtSourceRefs::Runtime {
                    base_color: None,
                    metallic_roughness: if mr_idx != u32::MAX {
                        merged_to_source.get(&mr_idx).copied()
                    } else {
                        None
                    },
                    normal: merged_to_source.get(&nm_idx).copied(),
                    emissive: None,
                },
            };
            let id = vt_manager.register_virtual_texture(
                device, mem,
                source_path,
                img.width, img.height,
                VtPackedFormat::NormalRoughnessEmissive,
                refs,
                command_pool, queue,
            )?;
            println!(
                "[VT] Registered NormalRoughness VT {} ({}x{}) mode={:?}{}",
                id, img.width, img.height, rt.mode,
                if rt.mode == VtMode::Prepacked {
                    format!(" disk_vt={}", disk_idx)
                } else {
                    format!(" nm={} mr={}", nm_idx,
                        if mr_idx != u32::MAX { mr_idx.to_string() } else { "none".into() })
                },
            );
            normal_vts.insert(key, id);
            id
        };
        mat.vt_normal_id = vt_id;
    }
}

// ── 3. Build metadata SSBO ──
let total_vts = albedo_vts.len() + normal_vts.len();
if total_vts > 0 {
    vt_manager.build_metadata_ssbo(mem, device, command_pool, queue)?;
    let prepacked_count = albedo_vts.keys()
        .chain(normal_vts.keys())
        .filter(|(m, _, _, _)| *m == VtMode::Prepacked)
        .count();
    let runtime_count = total_vts - prepacked_count;
    println!(
        "[VT] {} virtual texture(s) registered ({} runtime, {} prepacked), metadata uploaded",
        total_vts, runtime_count, prepacked_count,
    );

    // ── 4. Pre-seed coarse mips so the shader always has fallback data ──

            .chain(normal_vts.keys())
            .filter(|(m, _, _, _)| *m == VtMode::Prepacked)
            .count();
        let runtime_count = total_vts - prepacked_count;
        println!(
            "[VT] {} virtual texture(s) registered ({} runtime, {} prepacked), metadata uploaded",
            total_vts, runtime_count, prepacked_count,
        );

        // ── 4. Pre-seed coarse mips so the shader always has fallback data ──
        vt_manager.pre_seed_coarse_mips(device, command_pool, queue)?;
    }

    Ok(())
}

