/// Phase 5: Raycast from camera center and place a bullet hole decal
/// at the hit point. Attaches to dynamic bodies so decals move with them.
///
/// Raycast range: 200m. Uses physics world raycast (excludes character).
pub fn shoot_decal_at_crosshair(&mut self) -> bool {
    let cam_pos = self.scene.camera.position;
    let cam_fwd = self.scene.camera.forward();
    let ray = crate::physics::Ray::new(cam_pos, cam_fwd);

    if let Some(hit) = self.scene.physics_world.raycast_for_weapon(&ray, 200.0) {
        // Check if the hit body is dynamic (movable). If so, build
        // attachment info so the decal transforms with the body.
        let body_info = if self.scene.dynamic_body_descriptors.contains(&hit.collider_id) {
            let desc_idx = hit.collider_id as usize;
            if desc_idx < self.scene.descriptor_transforms.len() {
                Some((hit.collider_id, self.scene.descriptor_transforms[desc_idx]))
            } else {
                None
            }
        } else {
            None
        };

        let id = self.decal_manager.place_bullet_hole_attached(
            hit.point, hit.normal, None, body_info,
        );
        if id > 0 {
            let attached = if body_info.is_some() { " [attached]" } else { "" };
            println!(
                "[Decal] Bullet hole at ({:.1}, {:.1}, {:.1}) normal=({:.2}, {:.2}, {:.2}){}",
                hit.point.x, hit.point.y, hit.point.z,
                hit.normal.x, hit.normal.y, hit.normal.z,
                attached,
            );
            return true;
        }
    }
    false
}

