);
let group_count = (object_count + 63) / 64;
self.device.cmd_dispatch(cmd, group_count, 1, 1);

// Barrier: compute → indirect draw.
{
    let indirect_barrier = vk::BufferMemoryBarrier::default()
        .buffer(self.csm_indirect_buffers[fi].buffer)
        .offset(0)
        .size(INDIRECT_COMMAND_SIZE * MAX_OBJECTS as u64 * CSM_CASCADE_COUNT as u64)
        .src_access_mask(vk::AccessFlags::SHADER_WRITE)
        .dst_access_mask(vk::AccessFlags::INDIRECT_COMMAND_READ);
    let count_barrier = vk::BufferMemoryBarrier::default()
        .buffer(self.csm_draw_count_buffers[fi].buffer)
        .offset(0)
        .size(std::mem::size_of::<u32>() as u64 * CSM_CASCADE_COUNT as u64)
        .src_access_mask(vk::AccessFlags::SHADER_WRITE)
        .dst_access_mask(vk::AccessFlags::INDIRECT_COMMAND_READ);
