/// Phase 2: Adjust model facing offset by `delta` radians.
pub fn adjust_facing_offset(&mut self, delta: f32) {
    self.scene.character_controller.model_facing_offset += delta;
    // Wrap to [-PI, PI].
    let pi = std::f32::consts::PI;
    let offset = &mut self.scene.character_controller.model_facing_offset;
    while *offset > pi { *offset -= 2.0 * pi; }
    while *offset < -pi { *offset += 2.0 * pi; }
