// ── Dynamic test-instance forwarders ──
//
// Thin pass-throughs so `main.rs` can drive the geometry pool's
// alloc/free stress test from key bindings without reaching across
// the `Option<StreamingManager>` boundary. Each forwarder is a
// no-op when streaming is disabled.

/// Push one randomly-templated dynamic test instance. See
/// `StreamingManager::add_object` for semantics. Returns `None`
/// when streaming is disabled, no cleanup-eligible templates exist,
/// or the geometry pool is at hard budget.
pub fn add_dynamic_object(&mut self) -> Option<crate::streaming::DynamicObject> {
    match self.streaming_manager {
        Some(ref mut sm) => sm.add_object(),
        None => {
            println!("[Renderer] add_dynamic_object: streaming disabled.");
            None
        }
    }
}

/// Pop the most-recently-added dynamic test instance. See
/// `StreamingManager::remove_object` for semantics.
pub fn remove_dynamic_object(&mut self) -> Option<crate::streaming::DynamicObject> {
    match self.streaming_manager {
        Some(ref mut sm) => sm.remove_object(),
        None => {
            println!("[Renderer] remove_dynamic_object: streaming disabled.");
            None
        }
    }
}

/// Number of live dynamic test instances on the streaming
/// manager's LIFO stack. `0` when streaming is disabled.
pub fn dynamic_object_count(&self) -> usize {
    self.streaming_manager.as_ref()
        .map(|sm| sm.dynamic_object_count())
        .unwrap_or(0)
}

