        active.sort();
        println!("  Active sectors:  {:?}", active);

        // Print visible sector count (ring is too large to print).
        println!("  Visible:         {} sectors in Chebyshev ring",
            sm.visible_sectors().len());
    } else {
        println!("  Streaming: NOT ACTIVE");
    }

    if let Some(ref dsm) = self.descriptor_sector_map {
        let mut visible = 0u32;
        let mut hidden = 0u32;
        let mut always = 0u32;

        for i in 0..self.mesh_descriptors.len() {
            match dsm.owner(i) {
                crate::streaming::DescriptorOwner::AlwaysVisible => {
                    always += 1;
                }
                crate::streaming::DescriptorOwner::Sector(coord) => {
                    let is_vis = if let Some(ref sm) = self.streaming_manager {
                        dsm.is_visible(i, sm.visible_sectors())
                    } else {
                        true
                    };
                    if is_vis { visible += 1; } else { hidden += 1; }

                    // Print each sector-owned descriptor's status.
                    let status = if is_vis { "VISIBLE" } else { "HIDDEN " };
                    let name = &self.mesh_descriptors[i].name;
                    let tris = self.mesh_descriptors[i].index_count / 3;

                        dsm.is_visible(i, sm.visible_sectors())
                    } else {
                        true
                    };
                    if is_vis { visible += 1; } else { hidden += 1; }

                    // Print each sector-owned descriptor's status.
                    let status = if is_vis { "VISIBLE" } else { "HIDDEN " };
                    let name = &self.mesh_descriptors[i].name;
                    let tris = self.mesh_descriptors[i].index_count / 3;
                    println!("  desc[{:2}] {} sector({:2},{:2}) {:6} tris  '{}'",
                        i, status, coord.0, coord.1, tris, name);
                }
            }
        }
        println!("  ──────────────────────────────────────");
        println!("  Total: {} descriptors ({} always, {} sector-visible, {} sector-hidden)",
            self.mesh_descriptors.len(), always, visible, hidden);

        // Physics deactivation state.
        let deactivated = self.scene.physics_world.sector_deactivated.len();
        println!("  Physics: {} sector-deactivated bodies", deactivated);
    }

    // Light filtering.
    if let (Some(sm), Some(wc)) = (&self.streaming_manager, &self.world_config) {
        let light_set = sm.build_light_set(wc, self.scene.camera.position);
        println!("  Lights: {} full + {} penumbra = {} active (of {} total)",
            light_set.full_lights.len(), light_set.penumbra_lights.len(),
            light_set.total(), self.scene.lights.len());
        for &li in &light_set.full_lights {
            if li < wc.lights.len() {
                let lp = &wc.lights[li];
                println!("    light[{}] FULL    pos=({:.0},{:.0},{:.0}) r={:.0} {}",
                    li, lp.position[0], lp.position[1], lp.position[2],
                    lp.radius, lp.shadow_mode);
            }
        }
        for &li in &light_set.penumbra_lights {
            if li < wc.lights.len() {
                let lp = &wc.lights[li];
                println!("    light[{}] PENUMBRA pos=({:.0},{:.0},{:.0}) important_r={:.0}",
                    li, lp.position[0], lp.position[1], lp.position[2],
                    lp.effective_important_radius());
            }
        }
        // Show unloaded lights.
        for (i, lp) in wc.lights.iter().enumerate() {
            let tier = light_set.tier(i);
            if tier == crate::streaming::LightTier::Unloaded {
                println!("    light[{}] UNLOADED pos=({:.0},{:.0},{:.0})",
                    i, lp.position[0], lp.position[1], lp.position[2]);
            }
        }
    }

    println!();
}

