/// Collect current frame's RayTraced-mode lights as `GpuPointLight`
/// records. Used by the irradiance cache for spatial bin construction
/// each frame (orbit lights move; static lights still need their
/// position re-derived since `RtLightSet` is GPU-only).
fn collect_rt_gpu_lights(&self) -> Vec<crate::scene::GpuPointLight> {
    use crate::scene::PointLightShadowMode;

    self.scene.lights
        .iter()
        .filter(|l| l.shadow_mode == PointLightShadowMode::RayTraced)
        .map(|l| l.to_gpu())
        .collect()
}

pub fn profiling_snapshot(&self) -> ProfilingSnapshot {
    let vt_sub = self.vt_manager.as_ref()
        .map(|vt| vt.tick_subtimes_us)
        .unwrap_or([0u64; 6]);

    ProfilingSnapshot {
        frame_number: self.frame_number,
        gpu_pass_times_ms: self.gpu_pass_times_ms,
        cpu_section_times_ms: self.cpu_section_times_ms,
        gpu_total_ms: self.gpu_pass_times_ms.iter().sum(),
        cpu_total_ms: self.cpu_section_times_ms.iter().sum(),
        vt_subtimes_us: vt_sub,
        visible_count: self.visible_count,
        total_count: self.total_count,
        point_light_count: self.scene.point_light_count(),
        debug_view: self.debug_view_mode as u32,

            frame_number: self.frame_number,
            gpu_pass_times_ms: self.gpu_pass_times_ms,
            cpu_section_times_ms: self.cpu_section_times_ms,
            gpu_total_ms: self.gpu_pass_times_ms.iter().sum(),
            cpu_total_ms: self.cpu_section_times_ms.iter().sum(),
            vt_subtimes_us: vt_sub,
            visible_count: self.visible_count,
            total_count: self.total_count,
            point_light_count: self.scene.point_light_count(),
            debug_view: self.debug_view_mode as u32,
        }
    }
}

